const VOWEL_IDS=['a','e','i','o','u','oe','ue'];
const CONSONANT_IDS=Object.keys(CONS_DATA.info);
const consonantCaches={};
function consId(letter,text){let h=2166136261;for(const c of letter+text)h=Math.imul(h^c.charCodeAt(0),16777619);return 'q'+(h>>>0).toString(16).padStart(8,'0');}
function consScopedWord(letter,raw){
 const out={...raw,targets:(raw.allTargets||[]).filter(t=>t.letter===letter)};
 out.allTargets=out.targets;return out;
}
function consContext(letter,targetId,ti,id){
 const raw=CONS_DATA.records[targetId],frame=CONS_DATA.frames[ti],texts=[...frame.parts];
 texts[frame.quotePart]='“'+raw.text+'”';let offset=0,x=0,runNo=0;const parts=[],runs=[],targets=[],allTargets=[];
 for(let n=0;n<texts.length;n++){
  const base=CONS_DATA.parts[texts[n]],pruns=base.runs.map(r=>({...r,start:r.start+offset,end:r.end+offset,letters:r.letters?.map(t=>({...t,index:t.index+offset}))}));
  parts.push({text:texts[n],runs:pruns,advance:base.advance,offset});
  for(const r of pruns)runs.push({...r,x:r.x+x});
  if(n===frame.quotePart){
   for(const t of raw.allTargets||[])if(t.letter===letter){const index=t.index+offset+1,next={...t,index,run:pruns.findIndex(r=>index>=r.start&&index<r.end)+runNo};targets.push(next);allTargets.push(next);}
  }
  runNo+=pruns.length;offset+=texts[n].length+1;x+=base.advance+220;
 }
 const focusStart=parts[frame.quotePart].offset+1;
 const src=raw.source;
 return {id,text:texts.join(' '),runs,parts,advance:x-220,modern:'',kind:'authored-context',source:src,sourceHeading:raw.sourceHeading,sourcePage:raw.sourcePage,
  targets,allTargets,focusSpan:{start:focusStart,end:focusStart+raw.text.length},quotedTargetId:targetId,frameIndex:ti,
  compositionNote:raw.kind==='alphabet-example'?'Составленная фраза цитирует образец формы буквы. Образец не является словом; сама фраза не взята из исторического текста.':'Составленная фраза цитирует словарное написание. Меняется окружающий контекст; это не новое словарное слово и не историческая цитата.',
  provenance:{status:'authored-not-quoted',components:[...frame.components,{text:raw.text,modern:raw.modern||'образец '+CONS_DATA.info[letter].letter,source:src,heading:raw.sourceHeading||raw.text,page:raw.sourcePage||'',role:raw.kind==='dictionary'?'quoted-dictionary-spelling':'quoted-alphabet-form'}],ruleIds:['quoted-form',...frame.ruleIds],hasDerivedWordform:true,editorialReview:'Full native-speaker review pending.'}};
}
function consBank(letter){
 if(consonantCaches[letter])return consonantCaches[letter].bank;
 const meta=CONS_DATA.letters[letter],cache=new Map(),controls=new Map(),ids=new Set(meta.wordIds);
 const retrieve=id=>{
  if(cache.has(id))return cache.get(id);if(controls.has(id))return controls.get(id);
  let w;if(meta.recipes[id]){const [targetId,ti]=meta.recipes[id];w=consContext(letter,targetId,ti,id);}
  else if(CONS_DATA.records[id])w=consScopedWord(letter,CONS_DATA.records[id]);
  if(w)cache.set(id,w);return w;
 };
 const words=new Proxy({}, {get:(_,id)=>typeof id==='string'?retrieve(id):undefined,ownKeys:()=>[...ids],getOwnPropertyDescriptor:(_,id)=>ids.has(id)?{enumerable:true,configurable:true}:undefined});
 const bank={...meta,words,sources:CONS_DATA.sources,rules:CONS_DATA.rules};
 consonantCaches[letter]={bank,cache,controls,retrieve};return bank;
}
for(const [i,key] of CONSONANT_IDS.entries()){
 const item=CONS_DATA.info[key];
 COURSE_INFO[key]={...item,number:String(i+8).padStart(2,'0'),colorName:'в своём постоянном цвете',colorAfter:'в своём постоянном цвете',next:i<CONSONANT_IDS.length-1?CONS_DATA.info[CONSONANT_IDS[i+1]].letter:'повторение всего алфавита'};
 Object.defineProperty(COURSES,key,{enumerable:true,configurable:false,get:()=>({bank:consBank(key),font:CONS_DATA.font})});
}
function consonantExerciseWords(){
 const w=currentWord();if(state.mode==='guided')return [w];const f=F(),cache=consonantCaches[state.letter],seed=parseInt(w.id.slice(1,8),16)||0;
 const isContext=w.kind==='authored-context',target=CONS_DATA.records[w.quotedTargetId||w.id],len=visibleChars(target).length;
 let pool=isContext&&target.kind==='alphabet-example'?f.decoyAlphabetIds:(f.decoysByLength[String(len)]||f.fallbackDecoys);
 if(pool.length<2)pool=f.fallbackDecoys;
 const selected=[pool[seed%pool.length],pool[(seed+Math.max(1,Math.floor(pool.length/2)))%pool.length]];
 if(selected[0]===selected[1])selected[1]=pool[(pool.indexOf(selected[0])+1)%pool.length];
 const decoys=selected.map(tid=>{
  if(!isContext)return consScopedWord(state.letter,CONS_DATA.records[tid]);
  const id=consId(state.letter,tid+':'+w.frameIndex);if(!cache.controls.has(id))cache.controls.set(id,consContext(state.letter,tid,w.frameIndex,id));return cache.controls.get(id);
 });
 const out=[...decoys];out.splice(seed%3,0,w);return out;
}
