function joinSpans(text,seq){const ts=joinTokens(text),out=[];for(let i=0;i<=ts.length-seq.length;i++){const part=ts.slice(i,i+seq.length);if(part.map(t=>t.ch).join('')===seq)out.push({start:part[0].index,end:part.at(-1).index+1});}return out;}
function joinPairKeys(w,size=2){const ts=joinTokens(w.text),byIndex=new Map((w.allLetters||[]).map(t=>[t.index,t])),out=[];for(let i=0;i<=ts.length-size;i++){const p=ts.slice(i,i+size);if(!p.every(t=>joinNative(t.ch)))continue;const letters=p.map(t=>byIndex.get(t.index));if(letters.some(t=>!t))continue;out.push({seq:p.map(t=>t.ch).join(''),key:letters.map(t=>t.signature||t.g).join('|')});}return out;}
const joinWholeKey=w=>(w.allLetters||[]).map(t=>t.signature||t.g).join('|');
function joinRecipes(u){
 if(joinRecipeCache.has(u.id))return joinRecipeCache.get(u.id);
 const out=u.words.map(id=>({id:u.id+':w:'+id,target:id,frame:null})),targets=u.words.length?u.words:u.demos;
 for(let n=0;n<u.contextCount;n++){const target=targets[n%targets.length];out.push({id:u.id+':c:'+target+':'+n,target,frame:n});}
 out.sort((a,b)=>joinHashNumber(u.id+a.id)-joinHashNumber(u.id+b.id)||a.id.localeCompare(b.id));
 if(u.words.length){const n=out.findIndex(r=>r.frame===null&&r.target===u.words[0]);out.unshift(...out.splice(n,1));}
 joinRecipeCache.set(u.id,out);return out;
}
const joinUnit=()=>JOIN_DATA.units[joinView.unit];
const joinModeRecipes=u=>joinRecipes(u).slice(joinView.mode==='guided'?0:200,joinView.mode==='guided'?200:500);
const joinRecipe=()=>joinModeRecipes(joinUnit())[joinView.index];
const joinDone=(u,mode)=>joinRecipes(u).slice(mode==='guided'?0:200,mode==='guided'?200:500).filter(r=>joinProgress[u.id]?.[mode]?.[r.id]===true).length;
function joinRaw(w){return CONS_DATA.records[w.joinTargetId||w.id]||w;}
function joinContext(target,frame,id){const w=consContext('x1828',target,frame,id);return {...w,joinTargetId:target,compositionNote:'Учебная фраза цитирует целевое написание. Разные контексты не являются разными целевыми словами.'};}
function joinWord(r){return r.frame===null?CONS_DATA.records[r.target]:joinContext(r.target,r.frame,r.id);}
function joinControlPool(u,raw){
 const type=raw.kind==='alphabet-example'?'alphabet':'dictionary',cacheKey=u.id+'/'+type;
 if(joinControlCache.has(cacheKey))return joinControlCache.get(cacheKey);
 const patterns=new Set();
 if(u.seq){for(const id of [...u.words,...u.demos])for(const p of joinPairKeys(CONS_DATA.records[id],u.seq.length))if(p.seq===u.seq)patterns.add(p.key);}
 else for(const id of u.words)patterns.add(joinWholeKey(CONS_DATA.records[id]));
 const seen=new Set(),pool=[];
 for(const w of Object.values(CONS_DATA.records)){
  if(type==='alphabet'?(w.kind!=='alphabet-example'||visibleChars(w).length!==u.seq.length):w.kind!=='dictionary')continue;
  if(u.seq?(joinSpans(w.text,u.seq).length||joinPairKeys(w,u.seq.length).some(p=>patterns.has(p.key))):(w.modern?.toLowerCase().includes(u.pattern)||patterns.has(joinWholeKey(w))))continue;
  const key=joinWholeKey(w);if(!key||seen.has(key))continue;seen.add(key);pool.push(w.id);
 }
 if(pool.length<2)throw new Error('Недостаточно различимых сравнений: '+u.id);
 joinControlCache.set(cacheKey,pool);return pool;
}
function joinChoices(){
 const u=joinUnit(),r=joinRecipe(),token=u.id+'/'+joinView.mode+'/'+r.id;
 if(joinChoicesToken===token)return joinChoicesValue;
 const target=joinWord(r);let out=[target];
 if(joinView.mode==='blind'){
  const raw=CONS_DATA.records[r.target],pool=joinControlPool(u,raw),len=visibleChars(raw).length;
  const close=pool.filter(id=>Math.abs(visibleChars(CONS_DATA.records[id]).length-len)<=1),ids=close.length>=2?close:pool;
  const n=joinHashNumber(r.id),i=n%ids.length,j=(i+1+(n%Math.max(1,ids.length-1)))%ids.length;
  const selected=[ids[i],ids[j===i?(j+1)%ids.length:j]];
  out=selected.map(id=>r.frame===null?CONS_DATA.records[id]:joinContext(id,r.frame,'control:'+r.id+':'+id));out.splice(n%3,0,target);
 }
 joinChoicesToken=token;joinChoicesValue=out;return out;
}
function joinSvg(w,opts={}){const previous=FONT_DATA;FONT_DATA=CONS_DATA.font;try{return wordSvg(w,opts);}finally{FONT_DATA=previous;}}
function joinLabel(seq){return Array.from(seq).filter(joinNative).map(c=>`<strong style="color:${colorOf(c)}">${nameOf(c)}</strong>`).join('<span aria-hidden="true"> · </span>');}
function joinMini(u){return joinSvg(CONS_DATA.records[u.demos[0]],{color:true,fontSize:34});}
function joinSource(w,tag){const raw=joinRaw(w),s=CONS_DATA.sources[raw.source];if(!s)return '';const url=raw.sourceUrl||s.displayUrl||s.url;return `<a id="join-source-${tag}-${raw.id}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)}${raw.sourcePage?' · '+esc(raw.sourcePage):''} ↗</a>`;}
function joinCredits(tag){return `<details class="join-credits"><summary>Источники и состав материала</summary><p>${esc(JOIN_DATA.authorship)}</p><p><a id="join-book-${tag}" href="${JOIN_DATA.references.book}" target="_blank" rel="noopener noreferrer">Золтоева · тема дифтонгов, PDF 17–18</a> · <a id="join-modern-${tag}" href="${JOIN_DATA.references.modern}" target="_blank" rel="noopener noreferrer">Правила современной кириллицы · § 3, 5, 6</a> · <a id="join-unicode-${tag}" href="${JOIN_DATA.references.unicode}" target="_blank" rel="noopener noreferrer">Unicode · соединение и совпадение форм</a></p><p>Словарные написания и составленные контексты подписаны отдельно. Алфавитный образец не считается словом. Полная языковая вычитка корпуса и контекстов специалистом ещё требуется.</p></details>`;}
function joinMaterial(u){return `Словарных написаний: ${u.wordCount}. Учебных контекстов: ${u.contextCount}.${!u.wordCount?' В контекстах цитируется алфавитный образец; отдельное слово не заявляется.':''}`;}
function joinAmbiguity(){return `<p class="join-ambiguity">Некоторые формы А и Э, О и У совпадают. Учимся читать их с опорой на целое слово и правила. В заданиях для сравнения убраны неразличимые начертания.</p>`;}
function joinRuleDetail(u){const letters=u.keys.filter(k=>CONSONANT_IDS.includes(k));if(!letters.length)return '';return `<div class="join-letter-rule">${letters.map(k=>`<h3>Что проверить у ${COURSE_INFO[k].letter}</h3><p>${esc(TEACHING.letters[k].main)}</p>`).join('')}${u.group==='cv'&&u.keys[0]==='x1828'?'<p>После Н в этом соединении стоит гласная. Сравни точку в срединном образце с правилом Н перед гласной.</p>':''}</div>`;}
function joinICallout(){return `<section class="join-reading-callout"><div><h2>А что с ИИ?</h2><p>Есть слова с двумя письменными И подряд. Ещё есть одна И с двойным очертанием и долгое И в современном чтении. Рассмотрим три цветных примера рядом.</p></div>${button('Разобраться с ИИ →','join-ii','primary')}</section>`;}
function joinIGuide(){return sectionHeading('ИИ, двойная И и долгое И','Начнём с количества записанных букв, затем посмотрим на их форму и прочитаем целое слово.','ТРИ СЛУЧАЯ С БУКВОЙ И')+`<div class="join-index-actions">${button('← К долгим гласным и дифтонгам','join-tab','quiet-link','data-tab="reading"')}</div><p class="join-ambiguity">В современном чтении ИЙ обозначает долгое И. В старом письме отдельно узнаём две буквы И и двойное очертание одной И. Одинаковый синий цвет связывает каждую письменную И с её подписью.</p><div class="join-i-grid">${JOIN_DATA.iGuide.map((item,n)=>{const w=CONS_DATA.records[item.wordId],selected=joinISelections[n]??item.focus;return `<article class="join-i-card"><span class="mono">0${n+1} · И в записи: ${item.iCount}</span><h2>${esc(item.title)}</h2><div class="a-stage">${joinSvg(w,{color:true,selected,fontSize:80})}</div><div class="teach-letter-row" role="group" aria-label="Буквы примера ${n+1}">${visibleChars(w).map((t,i)=>button(`<small>${i+1}</small><strong style="color:${colorOf(t.ch)}">${nameOf(t.ch)}</strong>`,'join-i-letter','teach-letter'+(selected===t.index?' active':''),`data-guide="${n}" data-index="${t.index}" aria-label="Пример ${n+1}, буква ${nameOf(t.ch)}, место ${i+1}" aria-pressed="${selected===t.index}"`)).join('')}</div><div class="teach-modern"><span>Современное слово</span><strong lang="mn-Cyrl">${esc(w.modern)}</strong><p>${esc(item.meaning)}</p></div><p>${esc(item.rule)}</p><p class="join-unit-note">${esc(item.note)}</p><details class="join-word-source"><summary>Источник примера</summary>${joinSource(w,'ii-'+n)}</details>${n===0?button('Две И: 200 с цветом + 300 без →','join-open','primary','data-unit="vv-i-i"'):n===1?button('Форма одной И: 200 + 300 →','join-i-form','primary'):button('Долгое ИЙ: 200 + 300 →','join-open','primary','data-unit="reading-long-i"')}</article>`;}).join('')}</div><p class="join-material-note">Нажимай на подписи букв: рамка показывает выбранную букву в цельном написании. Для двух И сохранён один цвет буквы И; их места в слове подписаны разными номерами.</p>${joinCredits('ii-guide')}`;}
function joinWordNotes(w,tag){const raw=joinRaw(w);return `<div class="join-spelling"><span class="small-label">Буквы традиционного написания</span><div>${joinLabel(raw.text)}</div></div>${raw.modern?`<div class="teach-modern"><span>Современное слово — отдельное чтение</span><strong lang="mn-Cyrl">${esc(raw.modern)}</strong>${wordAuditRussianLine(raw)}${wordAlignmentExplanation(raw)}</div>`:wordAuditMissingCyrillic(raw,'Алфавитный образец соединения')}${w.parts?'<p class="context-kind">Составленный учебный контекст. Работаем только с записью в кавычках.</p>':''}<details class="join-word-source"><summary>Источник целевого написания</summary>${joinSource(w,tag)}</details>`;}
function joinUnitCard(u){return button(`${u.seq?joinMini(u):`<span class="join-reading-mark">${esc(u.label)}</span>`}<span class="join-card-label">${u.seq?joinLabel(u.seq):u.group==='long'?'Долгий гласный':'Дифтонг'}</span><small>${joinDone(u,'guided')} / 200 с цветом<br>${joinDone(u,'blind')} / 300 без подсказок</small>`,'join-open','join-card',`data-unit="${u.id}" aria-label="Изучить сочетание ${esc(u.label)}"`);}
function joinOpenIndex(tab='cv',letter=null){arcLeave();joinView.tab=JOIN_GROUPS[tab]?tab:'cv';if(letter){if(CONSONANT_IDS.includes(letter))joinView.letter=letter;else if(VOWEL_IDS.includes(letter))joinView.vowel=letter;}joinView.unit=null;state.section='combinations';state.screen='section';state.view='lesson';}
function joinOpen(id){if(!JOIN_DATA.units[id])return;arcLeave();joinView.unit=id;joinView.feedback='';state.section='combinations';state.screen='join-unit';state.view='lesson';}
function joinReset(){joinView.example=0;joinView.feedback='';joinView.wrong=false;joinView.assisted=false;joinView.help=false;joinView.selected=null;joinChoicesToken='';}
function joinStart(mode){joinView.mode=mode==='blind'?'blind':'guided';joinReset();const rs=joinModeRecipes(joinUnit()),n=rs.findIndex(r=>!joinProgress[joinView.unit]?.[joinView.mode]?.[r.id]);joinView.index=n<0?0:n;state.screen='join-practice';}
function joinPick(option,index=null){
 if(joinView.feedback==='correct')return;
 const u=joinUnit(),r=joinRecipe(),choices=joinChoices(),chosen=choices[option];if(!chosen)return;
 const raw=joinRaw(chosen),offset=chosen.focusSpan?.start||0;
 const target=joinRaw(joinWord(r));
 const ok=raw.id===target.id&&(u.seq?joinSpans(raw.text,u.seq).some(s=>s.start===index-offset):true);
 joinView.selected={option,index};
 if(ok){joinView.feedback='correct';joinView.wrong=false;
  if(!joinView.assisted){joinProgress[u.id]??={};joinProgress[u.id][joinView.mode]??={};joinProgress[u.id][joinView.mode][r.id]=true;try{localStorage.setItem(JOIN_PROGRESS_KEY,JSON.stringify(joinProgress));joinSaveError=false;}catch{joinSaveError=true;}}
 }else{joinView.wrong=true;if(joinView.mode==='blind')joinView.assisted=true;}
}
function joinNext(){const rs=joinModeRecipes(joinUnit());let n=(joinView.index+1)%rs.length;for(let k=0;k<rs.length;k++,n=(n+1)%rs.length)if(!joinProgress[joinView.unit]?.[joinView.mode]?.[rs[n].id])break;joinView.index=n;joinReset();}
function joinIndex(){
 const tab=joinView.tab,reading=tab==='reading',groups=reading?['long','diphthong']:[tab];
 let items=JOIN_UNITS.filter(u=>groups.includes(u.group));
 if(['cv','vc','cc'].includes(tab))items=items.filter(u=>u.keys.includes(joinView.letter));
 if(tab==='vv')items=items.filter(u=>u.keys[0]===joinView.vowel);
 const selector=['cv','vc','cc'].includes(tab)?`<label>Согласная<select id="join-consonant">${CONSONANT_IDS.map(k=>`<option value="${k}"${k===joinView.letter?' selected':''}>${COURSE_INFO[k].letter}</option>`).join('')}</select></label>`:tab==='vv'?`<label>Первая гласная<select id="join-vowel">${VOWEL_IDS.map(k=>`<option value="${k}"${k===joinView.vowel?' selected':''}>${COURSE_INFO[k].letter}</option>`).join('')}</select></label>`:'';
 return sectionHeading('Учимся узнавать сочетания','Сначала рассмотрим соединение с цветом. Затем найдём его в примерах и повторим без подсказок.','СЛЕДУЮЩИЙ ШАГ ПОСЛЕ БУКВ')+`<div class="join-index-actions">${button('Весь алфавит · 35 знаков','join-alphabet','secondary')}${button('Начать с Н · И →','join-open','primary','data-unit="cv-x1828-i"')}</div><nav class="join-tabs" aria-label="Тип сочетания">${Object.entries(JOIN_GROUPS).map(([id,label])=>button(label,'join-tab',id===tab?'active':'',`data-tab="${id}" aria-pressed="${id===tab}"`)).join('')}</nav>${selector?`<div class="join-selectors">${selector}<p>У каждого соединения свой набор: 200 с цветом и ещё 300 без подсказок.</p></div>`:''}${reading?`<section class="join-reading-intro"><h2>Долгий гласный и дифтонг — разные вещи</h2><p>У долгого гласного увеличена длительность. У дифтонга в одном слоге меняется качество звучания. Сначала изучаем частые записи АЙ, ЭЙ, ОЙ, УЙ, ҮЙ; затем — дополнительные. ИЙ относится к записи долгого И.</p><p>В традиционной записи могут сохраняться буквы, которых нет в современной кириллице. Поэтому разбор письма и современное чтение показаны отдельно.</p></section>`:joinAmbiguity()}${reading?`${joinICallout()}<h2 class="join-subtitle">Долгие гласные</h2><div class="join-grid reading-grid">${items.filter(u=>u.group==='long').map(joinUnitCard).join('')}</div><h2 class="join-subtitle">Дифтонги: частые и дополнительные записи</h2><div class="join-grid reading-grid">${items.filter(u=>u.group==='diphthong').map(joinUnitCard).join('')}</div><p class="join-rare-note">${esc(JOIN_DATA.rareNote)}</p><p class="join-rare-note">Записи ЯА, ЕЭ, ЁО, ЮУ, ЮҮ и другие случаи с йотированными буквами разбираются как чтение целых слов. Они не добавляют новых букв в традиционный алфавит.</p>`:`<div class="join-grid">${items.map(joinUnitCard).join('')}</div>${items.length?'':'<p class="library-note">В текущем словарном корпусе такого соседства не найдено. Слово не составляем искусственно.</p>'}`}<p class="join-material-note">Контексты с редкими соединениями отмечены отдельно и не выдаются за 500 разных слов. ЭЭ в таблице сочетаний — один дополнительный традиционный знак.</p>${joinCredits('index')}`;
}
function joinIntro(){const u=joinUnit(),sample=CONS_DATA.records[u.sample];return sectionHeading(u.kind==='reading'?'Читаем слова с '+u.label:'Соединение '+u.label,u.rule,u.kind==='reading'?'ОТ НАПИСАНИЯ К ЧТЕНИЮ':'УЧИМСЯ С НУЛЯ')+`<div class="join-index-actions">${button('← К сочетаниям','join-back','quiet-link')}${button('Весь алфавит','join-alphabet','quiet-link')}</div>${u.seq?`<section class="join-models"><h2>Одни буквы — разные соединения</h2><div>${u.demos.map((id,i)=>`<article><span>${['Отдельное соединение','В начале','В середине','В конце'][i]}</span>${joinSvg(CONS_DATA.records[id],{color:true,fontSize:48})}<div>${joinLabel(u.seq)}</div></article>`).join('')}</div><p>Это алфавитные модели. Они показывают соединение букв и сами по себе не объявляются словами или слогами. Тонкий переход вверх или вниз обозначает продолжение записи.</p></section>`:''}<div class="workspace teach-workspace"><section class="script-card"><div class="script-top"><span class="sample-label">РАЗБЕРЁМ ПРИМЕР</span><span class="teach-kind">${sample.kind==='dictionary'?'Словарное написание':'Алфавитный образец'}</span></div><div class="a-stage">${joinSvg(sample,{color:true,large:true})}</div>${joinWordNotes(sample,'intro')}</section><section class="panel teach-explanation"><h2 class="panel-title">Как узнавать и читать</h2><p class="teach-main-rule">${esc(u.rule)}</p>${joinRuleDetail(u)}<ol class="teach-steps">${u.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${joinAmbiguity()}<div class="practice-plan"><div><strong>200</strong><span>с цветом<br>${joinDone(u,'guided')} пройдено</span></div><div><strong>300</strong><span>без подсказок<br>${joinDone(u,'blind')} пройдено</span></div></div><p class="material-note">${joinMaterial(u)}</p><div class="panel-footer stacked">${button('Начать с цветом →','join-start','primary','data-mode="guided"')}${button('Тренироваться без подсказок','join-start','quiet-link','data-mode="blind"')}</div></section></div>${joinCredits(u.id)}`;}
function joinPractice(){
 const u=joinUnit(),rs=joinModeRecipes(u),choices=joinChoices(),sample=choices[joinView.example]||choices[0],raw=joinRaw(sample),guided=joinView.mode==='guided',help=guided||joinView.help,reveal=help||joinView.feedback==='correct';
 const option=Math.min(joinView.example,choices.length-1),offset=sample.focusSpan?.start||0;
 return sectionHeading(u.seq?'Найди соединение '+u.label:'Найди слово с '+u.label,(guided?'С цветными подсказками':'Без цвета и образца')+' · '+(u.seq?'ищем соседние письменные буквы':'узнаём современное чтение целого слова'),'ПРАКТИКА СОЧЕТАНИЙ')+`<div class="workspace a-workspace join-practice"><section class="script-card"><div class="script-top"><div class="mode-switch">${button('С цветом','join-mode','mode-button'+(guided?' active':''),`data-mode="guided" aria-pressed="${guided}"`)}${button('Без подсказок','join-mode','mode-button'+(!guided?' active':''),`data-mode="blind" aria-pressed="${!guided}"`)}</div></div>${choices.length>1?`<div class="example-tabs" aria-label="Примеры для сравнения">${choices.map((w,i)=>button('Пример '+(i+1),'join-example','example-tab'+(i===option?' active':''),`data-index="${i}" aria-pressed="${i===option}"`)).join('')}</div>`:''}<div class="a-stage join-stage" data-join-choice="${option}">${joinSvg(sample,{color:help,hits:Boolean(u.seq),selected:help?quotedReadingFocus(sample,raw,'practice',joinView.selected?.option===option?joinView.selected.index:-1):-1,large:true})}</div><div class="script-bottom"><span>↓ Сверху вниз${sample.parts?' · работа в кавычках':''}</span><span>${help?'Постоянные цвета букв':'Без цвета и образца'}</span></div></section><section class="panel exercise-panel"><div class="counter"><span>Пример ${joinView.index+1} / ${rs.length}</span><strong>${joinDone(u,joinView.mode)} / ${rs.length} пройдено</strong></div><h2 class="panel-title">${u.seq?'Где начинается '+esc(u.label)+'?':'В каком примере читается '+esc(u.label)+'?'}</h2><p class="instruction">${u.seq?`Найди ${u.seq.length} соседние буквы. Нажми на первую из них в записи${sample.parts?' в кавычках':''} или выбери её место кнопкой ниже.`:'Прочитай традиционное написание и выбери пример, в современном чтении которого есть '+esc(u.label)+'.'}${choices.length>1?' Сравни все три примера кнопками над записью.':''}</p>${help?`<div class="teach-practice-note"><strong>Правило</strong><p>${esc(u.rule)}</p>${joinRuleDetail(u)}</div>`:''}${u.seq?`<div class="join-position-buttons" role="group" aria-label="Первая буква сочетания в примере ${option+1}">${visibleChars(raw).map((t,i)=>button(help?`<small>${i+1}</small><strong style="color:${colorOf(t.ch)}">${nameOf(t.ch)}</strong>`:String(i+1),'join-pick','join-position',`data-option="${option}" data-index="${t.index+offset}" aria-label="Место ${i+1} сверху, пример ${option+1}"`)).join('')}</div>`:button('Выбрать '+(choices.length>1?'пример '+(option+1):'этот пример'),'join-pick','primary',`data-option="${option}"`)}${help?joinWordNotes(sample,'practice'):''}${joinView.feedback==='correct'?`<div class="feedback correct" role="status"><strong>Верно.</strong><p>${joinView.assisted?'Ответ после помощи или ошибки. Оставим его для самостоятельного повторения.':'Пример засчитан в выбранный режим.'}</p></div>`:joinView.wrong?'<div class="feedback error" role="status">Пока не это место. Сравни соединение ещё раз.</div>':''}${!guided&&!joinView.help&&joinView.feedback!=='correct'?button('Показать цвет и разбор','join-help','hint'):''}${joinView.help&&!guided?'<p class="callout">Помощь открыта. В самостоятельный прогресс этот ответ не войдёт.</p>':''}${!help&&reveal?`<details class="answer-analysis"><summary>Открыть цветной разбор ответа</summary><div class="a-stage">${joinAnswerDiagram()}</div>${joinWordNotes(joinWord(joinRecipe()),'answer')}</details>`:''}${joinSaveError?'<p role="status">Не удалось сохранить прогресс в браузере. Текущий ответ остаётся на экране.</p>':''}<div class="panel-footer">${button('К объяснению','join-explain','back')}${button('Следующий пример →','join-next','primary',joinView.feedback!=='correct'?'disabled':'')}</div></section></div>`;
}
function joinAlphabet(){return sectionHeading('Весь традиционный алфавит','Семь основных гласных, дополнительный знак ЭЭ и 27 согласных знаков, включая знаки для заимствований.','ПРОВЕРЯЕМ СОСТАВ АЛФАВИТА')+`<div class="join-index-actions">${button('К сочетаниям →','join-index','primary')}${button('Долгие гласные и дифтонги','join-tab','secondary','data-tab="reading"')}</div><p class="join-ambiguity">АА, ОО, УУ, ӨӨ и ҮҮ в современной кириллице показывают долгие гласные. Это не отдельные недостающие буквы старого письма. Ө и Ү — самостоятельные буквы, их изучаем отдельно от О и У.</p><div class="join-alphabet-grid">${[...VOWEL_IDS,...CONSONANT_IDS].map(k=>button(`${courseGlyph(k)}<strong style="color:${colorOf(COURSE_INFO[k].native)}">${COURSE_INFO[k].letter}</strong><small>${k==='x1827'?'один знак ЭЭ':COURSE_INFO[k].additional?'дополнительный знак':VOWEL_IDS.includes(k)?'гласная':'согласная'}</small>`,'join-letter','join-alphabet-card',`data-letter="${k}" aria-label="Урок буквы ${COURSE_INFO[k].letter}"`)).join('')}</div><p class="join-material-note">Это 35 букв монгольского ряда U+1820–U+1842, используемых в курсе. Знаки других письменностей в общем блоке Unicode и служебные переключатели форм не добавляются к этой таблице. Подпись из двух кириллических букв иногда называет один традиционный знак.</p>${joinCredits('alphabet')}`;}
function joinScreen(){return state.screen==='join-ii'?joinIGuide():state.screen==='join-practice'?joinPractice():state.screen==='join-unit'&&joinUnit()?joinIntro():joinIndex();}
function joinRoute(){if(state.screen==='join-ii')return '#combinations/i-guide';if(state.screen==='join-practice')return '#combinations/'+joinView.unit+'/practice/'+joinView.mode;if(state.screen==='join-unit')return '#combinations/'+joinView.unit;return '#combinations/'+joinView.tab+(['cv','vc','cc'].includes(joinView.tab)?'/'+joinView.letter:joinView.tab==='vv'?'/'+joinView.vowel:'');}
function joinLocation(p){if(p[0]==='alphabet'){state.section='alphabet';state.screen='section';return true;}if(p[0]!=='combinations')return false;if(p[1]==='i-guide'){joinOpenIndex('reading');state.screen='join-ii';return true;}if(JOIN_DATA.units[p[1]]){joinOpen(p[1]);if(p[2]==='practice')joinStart(p[3]);}else joinOpenIndex(JOIN_GROUPS[p[1]]?p[1]:'cv',p[2]);return true;}
function joinAction(e){
 const hit=e.target.closest('[data-letter-index]'),stage=hit?.closest('[data-join-choice]');
 if(stage&&state.section==='combinations'&&state.screen==='join-practice'){joinPick(Number(stage.dataset.joinChoice),Number(hit.dataset.letterIndex));render();return true;}
 const b=e.target.closest('button[data-action^="join-"]');if(!b||b.disabled)return false;const a=b.dataset.action;let nav=false;
 if(a==='join-ii'){joinOpenIndex('reading');state.screen='join-ii';nav=true;}
 if(a==='join-i-letter')joinISelections[Number(b.dataset.guide)]=Number(b.dataset.index);
 if(a==='join-i-form'){openVowel('i');state.form='medial-double';state.screen='form';nav=true;}
 if(a==='join-open'){joinOpen(b.dataset.unit);nav=true;}
 if(a==='join-index'||a==='join-back'){joinOpenIndex(joinView.tab);nav=true;}
 if(a==='join-tab'){joinOpenIndex(b.dataset.tab);nav=true;}
 if(a==='join-letter-index'){joinOpenIndex(CONSONANT_IDS.includes(b.dataset.letter)?'cv':'vv',b.dataset.letter);nav=true;}
 if(a==='join-alphabet'){arcLeave();state.section='alphabet';state.screen='section';nav=true;}
 if(a==='join-letter'){VOWEL_IDS.includes(b.dataset.letter)?openVowel(b.dataset.letter):openConsonant(b.dataset.letter);nav=true;}
 if(a==='join-start'||a==='join-mode'){joinStart(b.dataset.mode);nav=true;}
 if(a==='join-explain'){state.screen='join-unit';nav=true;}
 if(a==='join-example')joinView.example=Number(b.dataset.index);
 if(a==='join-pick')joinPick(Number(b.dataset.option),b.dataset.index===undefined?null:Number(b.dataset.index));
 if(a==='join-next')joinNext();
 if(a==='join-help'){joinView.help=true;joinView.assisted=true;joinView.wrong=false;}
 if(nav)syncSiteRoute();render();if(nav)window.scrollTo({top:0,behavior:'instant'});return true;
}
function joinSelect(e){if(!['join-consonant','join-vowel'].includes(e.target.id))return false;if(e.target.id==='join-consonant')joinView.letter=e.target.value;else joinView.vowel=e.target.value;syncSiteRoute(false);render();return true;}
function joinLetterStrip(letter){
 const cons=CONSONANT_IDS.includes(letter),items=JOIN_UNITS.filter(u=>u.group===(cons?'cv':'vc')&&u.keys.includes(letter));
 return `<section class="join-letter-strip"><div class="section-title"><h2>${COURSE_INFO[letter].letter} в сочетаниях</h2>${letter==='i'?button('ИИ и двойная форма И →','join-ii','quiet-link'):''}${button('Все сочетания →','join-letter-index','quiet-link',`data-letter="${letter}"`)}</div><p>Цвет каждой буквы сохраняется. Нажми на соединение, чтобы разобрать его и потренироваться.</p><div class="join-strip" role="group" aria-label="Цветные соединения буквы ${COURSE_INFO[letter].letter}">${items.map(u=>button(`${joinMini(u)}<span>${joinLabel(u.seq)}</span>`,'join-open','join-strip-card',`data-unit="${u.id}" aria-label="Соединение ${u.label}"`)).join('')}</div><p class="small-label">Алфавитные модели соединения · не список самостоятельных слов.</p></section>`;
}
function joinWordLinks(w){const text=w.quotedTargetId?CONS_DATA.records[w.quotedTargetId].text:w.focusSpan?w.text.slice(w.focusSpan.start,w.focusSpan.end):w.text;const ts=joinTokens(text),pairs=[];for(let n=0;n<ts.length-1;n++){const p=ts[n].ch+ts[n+1].ch;if(Array.from(p).every(joinNative)&&!pairs.includes(p))pairs.push(p);}if(!pairs.length)return '';return `<details class="join-word-breakdown"><summary>Цветные сочетания в этом примере</summary><p>Подписи называют письменные буквы. Для чтения всего слова смотри отдельную кириллическую строку.</p><div class="join-word-pairs">${pairs.map(seq=>{const u=JOIN_DATA.units[JOIN_SEQ_INDEX.get(seq)];return u?button(`${joinMini(u)}<span>${joinLabel(seq)}</span>`,'join-open','join-pair-link',`data-unit="${u.id}" aria-label="Разобрать соединение ${u.label}"`):`<span class="join-pair-link">${joinLabel(seq)}</span>`;}).join('')}</div></details>`;}
function joinReadingCallout(){return `<section class="join-reading-callout"><div><h2>Соединения, долгие гласные и дифтонги</h2><p>После объяснения правила потренируйся узнавать буквы вместе и связывать старое написание с современным чтением.</p></div>${button('Открыть мини-уроки →','join-tab','primary','data-tab="reading"')}</section>`;}
function eeRareForms(){return `<details class="rare-forms"><summary>Один знак ЭЭ и редкие формы</summary><p>Традиционный знак ЭЭ используется в заимствованиях. Его название не означает две буквы Э и не служит общим способом записи современного долгого «ээ».</p><p>У каждой из четырёх позиционных форм есть 200 заданий с цветом и 300 без. Если словарных примеров мало, используются разные составленные контексты с цитируемым написанием или алфавитным образцом. Их число не называется числом разных слов.</p><a id="ee-variants" href="https://www.unicode.org/notes/tn57/utn57-mong-4.pdf#page=15" target="_blank" rel="noopener noreferrer">Основание форм · UTN 57, таблица 4, PDF 15</a></details>`;}

