const ARCADE_STORAGE='mongol-reading-games-v1';
function readArcadeSave(){
 try{const v=JSON.parse(localStorage.getItem(ARCADE_STORAGE)||'{}');return {history:Array.isArray(v.history)?v.history.slice(-100):[],best:v.best&&typeof v.best==='object'?v.best:{},totals:v.totals&&typeof v.totals==='object'?v.totals:{},settings:v.settings||{}};}catch{return {history:[],best:{},totals:{},settings:{}};}
}
let arcadeSave=readArcadeSave(),arcade=null,arcadeInterval=null,arcadeSaveFailed=false;
const arcadeSettings={mode:arcadeSave.settings.mode==='blind'?'blind':'guided',seconds:[30,60,120].includes(Number(arcadeSave.settings.seconds))?Number(arcadeSave.settings.seconds):0,group:['vowels','consonants','all'].includes(arcadeSave.settings.group)?arcadeSave.settings.group:'vowels',letter:ARCADE_INFO[arcadeSave.settings.letter]||arcadeSave.settings.letter==='mixed'?arcadeSave.settings.letter:state.letter,form:arcadeSave.settings.form||'initial'};
