 const slots=targets.map(t=>arcPiece(w,t)),tokens=slots.map((p,i)=>({...p,token:'t'+i}));
 const shapes=new Set(slots.map(p=>p.shape));
 const decoy=arcFormPieces().find(p=>!shapes.has(p.shape))||arcCrossLetterPieces(1,shapes)[0];if(decoy)tokens.push({...decoy,token:'d'});
 return {...base,w,word,piece,slots,tokens:arcShuffle(tokens,seed+number*41),filled:[],used:[],slot:slots[0]?.index};
