function arcHandle(action,b){
 if(action==='arc-launch'){arcPrepare(b.dataset.game);syncSiteRoute();render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(action==='arc-back'){arcLeave();state.screen='game-setup';syncSiteRoute();render();return;}
 if(action==='arc-begin'){if(arcade?.stage==='ready'||arcade?.stage==='results')arcBegin();render();return;}
 if(action==='arc-resume'){arcResume();render();return;}
 if(!arcGuard())return;
 const q=arcade.task,r=arcade.round;
 if(action==='arc-pause')arcPause();
 else if(action==='arc-finish')arcFinish('finish');
 else if(action==='arc-next')arcNext();
 else if(action==='arc-help'&&!q.done&&!q.help){q.help=true;r.hints++;q.feedback='Подсказка открыта. Этот пример останется тренировочным.';}
 else if(!q.done){
  if(action==='arc-slot')q.slot=Number(b.dataset.index);
  if(action==='arc-tile'){
   const p=q.tokens.find(p=>p.token===b.dataset.token),slot=q.slots.find(s=>s.index===q.slot);
   if(p&&slot&&!q.used.includes(p.token)&&!q.filled.includes(slot.index)){
    if(p.shape===slot.shape){q.used.push(p.token);q.filled.push(slot.index);r.answers++;q.feedback='Деталь на месте.';q.slot=q.slots.find(s=>!q.filled.includes(s.index))?.index;if(q.filled.length===q.slots.length)arcSolve();}
    else arcWrong('tile/'+slot.index+'/'+p.shape,'Здесь нужна другая форма. Посмотри на место буквы в соединении.');
   }
  }
  if(action==='arc-option'){
   const p=q.options.find(p=>p.option===b.dataset.option);
   if(p){if(p.shape===q.piece.shape){r.answers++;arcSolve();}else arcWrong('option/'+p.option,'Это другое очертание. Сравни форму и её место в слове.');}
  }
  if(action==='arc-bridge'){
   const p=q.options.find(p=>p.id===b.dataset.option);
   if(p){if(p.word.id===q.w.id){r.answers++;arcSolve();}else arcWrong('bridge/'+p.id,'Это другое слово. Сверь буквы сверху вниз или открой помощь.');}
  }
  if(action==='arc-copy'){
   const index=Number(b.dataset.index);
   if(index===q.piece.index){r.answers++;arcSolve();}else arcWrong('copy/'+index,'В этом месте копия совпадает с оригиналом. Продолжай сравнивать сверху вниз.');
  }
  if(action==='arc-memory-close'){q.open=[];q.mismatch=false;q.feedback='';}
  if(action==='arc-memory'&&!q.mismatch){
   const id=Number(b.dataset.card),card=q.cards.find(c=>c.id===id);
   if(card&&!q.matched.includes(card.pair)&&!q.open.includes(id)){
    q.open.push(id);
    if(q.open.length===2){const [a,c]=q.open.map(id=>q.cards.find(c=>c.id===id));if(a.pair===c.pair){q.matched.push(a.pair);q.open=[];r.answers++;q.feedback='Пара найдена.';if(q.matched.length===q.pairs.length)arcSolve();}else{q.mismatch=true;arcWrong('pair/'+[a.id,c.id].sort().join('/'),'Эти карточки относятся к разным формам. Рассмотри их и закрой пару.');}}
   }
  }
 }
 render();
}
function arcNative(w,opts={}){return arcWordSvg(w,{color:arcade.mode==='guided'||arcade.task?.help,...opts});}
