  return `<div class="arc-puzzle-layout"><div class="arc-word-stage">${arcPuzzleWord(q.word,hidden)}<div class="arc-slots" aria-label="Места букв сверху вниз">${q.slots.map(p=>{const n=chars.findIndex(c=>c.index===p.index)+1,filled=q.filled.includes(p.index);return button(`${n}${filled?' ✓':' ?'}`,'arc-slot','arc-slot'+(q.slot===p.index?' selected':'')+(filled?' filled':''),`data-index="${p.index}" aria-label="${filled?'Заполнено':'Пустое место'} ${n}" aria-pressed="${q.slot===p.index}"${filled||q.done?' disabled':''}`);}).join('')}</div></div><div><h3>Детали соединения</h3><p class="arc-small">${q.done?'Все буквы на месте.':`Сейчас заполняем место ${chars.findIndex(c=>c.index===q.slot)+1} сверху.`}</p><div class="arc-tiles">${q.tokens.map((p,i)=>button(arcPieceSvg(p)+`<span>Деталь ${i+1}</span>`,'arc-tile','arc-tile',`data-token="${p.token}" draggable="${!q.used.includes(p.token)}" aria-label="Выбрать деталь ${i+1}"${q.used.includes(p.token)||q.done?' disabled':''}`)).join('')}</div>${arcScheme(q.word)}</div></div>`;
