const priorSiteContent=siteContent;
siteContent=function(){if(state.screen==='vc-index')return vcIndexScreen();if(state.screen==='vc-family')return vcFamilyScreen();if(state.screen==='vc-practice')return vcPractice();if(state.screen==='rule-map')return ruleMap();if(state.section==='rules')return rulesScreen();return priorSiteContent();};
siteHeader=function(){
 const inCourse=['vowels','consonants'].includes(state.section)&&state.screen!=='section';
 const section=state.section==='alphabet'?'combinations':state.section;
 return `<header class="header"><div class="header-inner simple-header"><button class="brand brand-home" data-action="home" aria-label="На главную"><span class="brand-name">Монгол бичиг</span><span class="brand-sub">Читаем с нуля</span></button><label class="simple-section-label">Раздел<select id="simple-section" aria-label="Выбрать раздел"><option value="home"${section==='home'?' selected':''}>Главная</option>${Object.entries(SITE_SECTIONS).map(([id,title])=>`<option value="${id}"${section===id?' selected':''}>${title}</option>`).join('')}</select></label></div></header>${inCourse?`<div class="course-controls simple-course-controls"><label>Буква<select id="simple-letter" aria-label="Выбрать букву"><optgroup label="Гласные">${VOWEL_IDS.map(id=>`<option value="${id}"${id===state.letter?' selected':''}>${COURSE_INFO[id].letter}${id==='x1827'?' · дополнительный знак':''}</option>`).join('')}</optgroup><optgroup label="Согласные">${CONSONANT_IDS.map(id=>`<option value="${id}"${id===state.letter?' selected':''}>${COURSE_INFO[id].letter}</option>`).join('')}</optgroup></select></label><a id="simple-course-view" href="#${letterSection()}/${state.letter}${state.view==='reader'?'':'/reading/'+state.form+'/guided'}">${state.view==='reader'?'К объяснению буквы':'Чтение с разбором →'}</a></div>`:''}`;
};
pageIntro=function(title,desc,eyebrow=`БУКВА ${course().number} · ${course().letter}`){return sectionHeading(title,desc,eyebrow);};
const priorTeachRulePanel=teachingRulePanel;
teachingRulePanel=function(f,w){let h=priorTeachRulePanel(f,w);return h.replace(/<div class="panel-footer stacked">[\s\S]*?<\/div><\/div><\/section>$/,`<div class="simple-fields">${simpleModeSelect()}</div><div class="panel-footer">${button('Начать практику →','simple-form-start','primary')}</div></div></section>`);};
function simpleExtras(){return `<details class="simple-details"><summary>Все формы ${course().letter} · ${BANK.forms.length} наборов</summary>${catalog()}</details><details class="simple-details"><summary>Сочетания с этой буквой</summary>${joinLetterStrip(state.letter)}</details>${teachingCredits()}${rareForms()}`;}
teachFormIntro=function(){const f=F(),w=teachingSample(f);return pageIntro(f.title,teachingFormInfo().rule)+`<p class="simple-back"><a id="simple-form-back" href="#${letterSection()}/${state.letter}">← К знакомству с буквой ${course().letter}</a></p><div class="workspace a-workspace teach-workspace">${teachingWordPanel(w,f)}${teachingRulePanel(f,w)}</div>`+simpleExtras();};
const priorTeachLetterIntro=teachLetterIntro;
teachLetterIntro=function(){let h=priorTeachLetterIntro(),suffix=joinLetterStrip(state.letter)+teachingCredits()+catalog()+rareForms()+editorNote();h=h.replace(suffix,simpleExtras());h=h.replace(button('Посмотреть все формы','catalog','quiet-link'),'');return h;};
const priorLetterButtons=letterButtons;
letterButtons=function(w,color){const h=priorLetterButtons(w,color);return state.screen==='practice'&&state.view!=='reader'?`<details class="simple-details"><summary>Выбрать букву по номеру</summary>${h}</details>`:h;};
const priorJoinIntro=joinIntro;
joinIntro=function(){let h=priorJoinIntro();h=h.replace(/<section class="join-models">([\s\S]*?)<\/section>/,'<details class="simple-details"><summary>Позиционные модели соединения</summary><section class="join-models">$1</section></details>');h=h.replace(/<div class="panel-footer stacked">[\s\S]*?<\/div><\/section><\/div>/,`<div class="simple-fields">${simpleModeSelect()}</div><div class="panel-footer">${button('Начать практику →','simple-join-start','primary')}</div></section></div>`);return h;};
const priorJoinIndex=joinIndex;
joinIndex=function(){return priorJoinIndex().replace(/<div class="join-index-actions">[\s\S]*?<\/div>/,'<p class="simple-back"><a id="join-back-compare" href="#combinations/compare">← К сравнениям гласных</a></p>').replace(/<nav class="join-tabs"[\s\S]*?<\/nav>/,`<div class="simple-fields"><label>Тип соединения<select id="simple-join-type" aria-label="Тип соединения">${Object.entries(JOIN_GROUPS).map(([id,label])=>`<option value="${id}"${joinView.tab===id?' selected':''}>${label}</option>`).join('')}</select></label></div>`);};
homeScreen=function(){return `<section class="library-hero"><div class="eyebrow">МОНГОЛЬСКОЕ ПИСЬМО</div><h1>Научимся читать<br>шаг за шагом</h1><p>Ты читаешь кириллицу. Здесь свяжем знакомое слово с традиционной записью: объясним правило, разберём буквы цветом и потренируем чтение.</p><div class="hero-actions">${button('Начать с буквы А →','open-vowel','primary','data-letter="a"')}</div></section><section class="simple-learning-path"><div class="section-title"><h2>Три шага обучения</h2><span>Без спешки</span></div><a id="path-letters" href="#vowels"><span>01</span><div><h3>Узнаём буквы</h3><p>Гласные и согласные, все изучаемые формы и соединения.</p></div><b>→</b></a><a id="path-comparisons" href="#combinations/compare"><span>02</span><div><h3>Читаем слова</h3><p>А — АА — АЙ и остальные сравнения: цвет → самостоятельное чтение.</p></div><b>→</b></a><a id="path-rules" href="#rules"><span>03</span><div><h3>Понимаем классическую запись</h3><p>36 коротких уроков: правила, окончания и первая строка с разбором.</p></div><b>→</b></a></section><div class="simple-home-links"><a id="home-cons" href="#consonants">К согласным →</a><a id="home-games" href="#games">Закрепить в игре →</a><a id="home-map" href="#rules/map">Карта правил →</a></div>`;};
const priorVowelsScreen=vowelsScreen;
vowelsScreen=function(){return priorVowelsScreen().replace(/<div class="section-actions">[\s\S]*?<\/div>$/,`<p class="simple-back"><a id="vowels-compare" href="#combinations/compare">После букв: сравнения А — АА — АЙ и остальных гласных →</a></p>`);};
const priorRuleExample=ruleExample;
ruleExample=function(example,index){const w=RULE_ASSETS.words[example.word];let h=priorRuleExample(example,index);if(w.classical)h=h.replace('<div class="rule-modern">',`<div class="rule-classical"><span>Условная передача классической записи</span><strong>${esc(w.classical)}</strong></div><div class="rule-modern">`);return h.replace('<div class="rule-example-kind">undefined</div>','<div class="rule-example-kind">Учебное предложение</div>');};
const priorRuleLesson=ruleLesson;
ruleLesson=function(){return priorRuleLesson().replace(/<div class="section-actions">([\s\S]*?)<\/div>/,(whole,inside)=>'<div class="section-actions">'+inside.replace(/<button class="secondary"/g,'<button class="quiet-link"')+'</div>');};
ruleIndex=function(){const next=READING_RULES.lessons.find(l=>!ruleIsComplete(l))||READING_RULES.lessons[0],group=READING_RULES.groups[ruleStage];return sectionHeading('Правила чтения',READING_RULES.subtitle,'ОТ ЗНАКОВ К КЛАССИЧЕСКОМУ ТЕКСТУ')+`<section class="rule-course-start"><div><span class="status-pill">В своём темпе · без таймера</span><h2>Одно правило за один шаг</h2><p>Короткое объяснение, примеры с разбором и три вопроса. Можно открыть любой урок.</p><div class="rule-course-progress"><span>${ruleCompletedCount()} / 36 мини-уроков пройдено</span><progress max="36" value="${ruleCompletedCount()}" aria-label="Пройдено мини-уроков"></progress></div></div>${button(ruleCompletedCount()?'Продолжить →':'Начать первый урок →','rule-open','primary',`data-id="${next.id}"`)}</section><div class="simple-fields rule-stage"><label>Этап обучения<select id="rule-stage" aria-label="Этап обучения">${READING_RULES.groups.map((g,i)=>`<option value="${i}"${i===ruleStage?' selected':''}>${i+1}. ${g.title}</option>`).join('')}</select></label><a id="rules-map-link" href="#rules/map">Карта правил и справка →</a></div><section aria-label="${esc(group.title)}"><div class="vc-family-list">${READING_RULES.lessons.filter(l=>l.group===ruleStage).map(l=>`<button class="vc-family-row rule-row" data-action="rule-open" data-id="${l.id}"><span class="mono">${String(l.order).padStart(2,'0')}</span><div><strong>${esc(l.title)}</strong><p>${esc(l.rule)}</p></div><span>${ruleIsComplete(l)?'Пройдено ✓':'3 вопроса'}</span><b aria-hidden="true">→</b></button>`).join('')}</div></section><details class="simple-details"><summary>На чём основаны уроки</summary><p>Темы сверены с пособием О. Ф. Золтоевой; сведения об устройстве письма — с Unicode и W3C. Объяснения и проверочные задания составлены для тренажёра. В каждом уроке открываются страницы источников и происхождение примеров.</p><p>${esc(CLASSIC.scope)}</p></details>`;};
function ruleMap(){return sectionHeading('Карта правил чтения','Проверяем, где объясняется каждая тема. Наличие урока не равно освоению темы: личный прогресс хранится отдельно.','ПРОГРАММА КУРСА')+`<p class="simple-back"><a id="rules-map-back" href="#rules">← К мини-урокам</a></p><div class="rule-map-list">${CLASSIC.coverage.map((row,n)=>`<article><h2>${esc(row.topic)}</h2><span class="status-pill">Есть объяснение и проверка</span><p>${row.lessons.map((id,i)=>`<a id="coverage-${n}-${i}" href="#rules/${id}">${ruleById(id).order}. ${esc(ruleById(id).title)}</a>`).join(' · ')}</p><a id="coverage-book-${n}" href="${VC.sources.book}#page=${row.pages[0]}" target="_blank" rel="noopener noreferrer">Пособие · PDF, с. ${row.pages.join(', ')}</a></article>`).join('')}</div><details class="simple-details ending-reference"><summary>Справка: узнаём частые окончания</summary><p>Это ориентиры чтения, не полный курс образования форм. Сначала найди основу, затем окончание; значение и вариант проверяй по предложению и словарю. В первом столбце даны примеры в современной монгольской кириллице.</p>${CLASSIC.endingReference.map((group,n)=>`<h2>${group.title}</h2><div class="ending-table-wrap"><table><thead><tr><th>Запись</th><th>Что узнаём</th><th>На что обратить внимание</th></tr></thead><tbody>${group.rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><a id="ending-source-${n}" href="${VC.sources.book}#page=${n?32:23}" target="_blank" rel="noopener noreferrer">Основание: пособие, PDF с. ${n?'32–36':'23–30'}</a></p>`).join('')}</details><section class="vc-intro-note"><h2>Что ещё нужно для свободного чтения</h2><p>Проверка охватывает базовую орфографию и первые словоформы. Следующий этап — связные классические тексты с нарастающей сложностью, словарь и дальнейшая грамматика. Чтение рукописей и всех исторических почерков требует отдельной практики.</p><p>Весь унаследованный словарный корпус и составленные контексты ещё должны пройти полную вычитку специалистом. Поэтому карта не выдаёт наличие 36 уроков за завершённый курс свободного чтения.</p></section>`;}

const priorConsSectionScreen=consSectionScreen;
consSectionScreen=function(){return priorConsSectionScreen().replace(/<h2 class="cons-group-title">Дополнительные знаки для заимствований<\/h2>([\s\S]*?)(<div class="library-note">)/,'<details class="simple-details"><summary>Дополнительные знаки для заимствований</summary>$1</details>$2');};

// Add one reading route while retaining every prior bank and storage key.
const PR=PHRASE_DATA,PR_PROGRESS_KEY='mongol-phrase-reading-v1';
Object.assign(CONS_DATA.font.glyphs,PR.font.glyphs);
Object.assign(CONS_DATA.font.ligatureCarets,PR.font.ligatureCarets);
const prLabels={vowels:SITE_SECTIONS.vowels,consonants:SITE_SECTIONS.consonants,combinations:SITE_SECTIONS.combinations,phrases:'Читаем фразы',rules:SITE_SECTIONS.rules,games:SITE_SECTIONS.games};
for(const k of Object.keys(SITE_SECTIONS))delete SITE_SECTIONS[k];Object.assign(SITE_SECTIONS,prLabels);
function prRead(){try{const p=JSON.parse(localStorage.getItem(PR_PROGRESS_KEY)||'{}');return {studied:p?.studied&&typeof p.studied==='object'&&!Array.isArray(p.studied)?p.studied:{},clean:p?.clean&&typeof p.clean==='object'&&!Array.isArray(p.clean)?p.clean:{}};}catch{return {studied:{},clean:{}};}}
let prProgress=prRead(),prSaveError=false;
const prState={stage:0,id:'ene-nom',mode:'guided',word:0,letter:0,revealed:false,assisted:false,done:false,wrong:false};
const prBridgeSelection={};
const prCard=()=>PR.cards.find(c=>c.id===prState.id)||PR.cards[0];
const prWords=c=>c.lines.flat();
const prWord=()=>PR.words[prWords(prCard())[prState.word]||prWords(prCard())[0]];
function prPersist(){try{localStorage.setItem(PR_PROGRESS_KEY,JSON.stringify(prProgress));prSaveError=false;}catch{prSaveError=true;}}
function prReset(){prState.word=0;prState.letter=0;prState.revealed=false;prState.assisted=false;prState.done=false;prState.wrong=false;}
function prIndex(stage=prState.stage){arcLeave();prState.stage=Math.max(0,Math.min(3,Number(stage)||0));state.section='phrases';state.screen='phrase-index';state.ruleId=null;prReset();}
function prOpen(id='ene-nom',mode='guided'){
 arcLeave();const c=PR.cards.find(c=>c.id===id)||PR.cards[0];prState.id=c.id;prState.stage=c.stage;prState.mode=mode==='blind'?'blind':'guided';state.section='phrases';state.screen='phrase-reader';state.ruleId=null;prReset();
}
function prMark(kind){prProgress[kind][prCard().id]=prCard().version;prPersist();}
function prHelp(){if(prState.mode!=='blind'||prState.done)return;prState.revealed=true;prState.assisted=true;prState.wrong=false;}
function prAnswer(n){
 if(state.screen!=='phrase-reader'||prState.mode!=='blind'||prState.done||!Number.isInteger(n)||n<0||n>2)return;
 if(n!==prCard().question.answer){prState.wrong=true;prState.assisted=true;return;}
 prState.done=true;prState.wrong=false;prState.revealed=true;if(!prState.assisted)prMark('clean');
}
function prNext(){
 if(state.screen!=='phrase-reader'||prState.mode==='blind'&&!prState.done)return;
 const c=prCard();prMark('studied');const next=PR.cards[c.order];
 if(next)prOpen(next.id,prState.mode);else prIndex(c.stage);
}
function prChars(w){return visibleChars(w);}
function prGroupStyle(w,g){
 const chars=prChars(w),colors=[...new Set(g.native.map(i=>colorOf(chars[i].ch)))];
 if(colors.length===1)return `color:${colors[0]}`;
 const stops=colors.flatMap((c,i)=>[`${c} ${i*100/colors.length}%`,`${c} ${(i+1)*100/colors.length}%`]).join(',');
 return `background-image:linear-gradient(90deg,${stops});background-clip:text;-webkit-background-clip:text;color:transparent`;
}
function prBridge(w,b,key,selected=null,{meaning='',note=true,focus=null}={}){
 const chars=prChars(w);let offset=0;return `<div class="pr-bridge" data-bridge="${esc(key)}"><div class="pr-bridge-label">Буквы в записи · сверху вниз</div><div class="pr-letter-row" role="group" aria-label="Кириллические подписи письменных букв">${chars.map((c,i)=>button(`<small>${i+1}</small><strong style="color:${colorOf(c.ch)}">${nameOf(c.ch)}</strong>`,'pr-letter','pr-letter'+(i===selected?' selected':''),`data-key="${esc(key)}" data-index="${i}" aria-label="Письменная ${nameOf(c.ch)}, место ${i+1}" aria-pressed="${i===selected}"`)).join('')}</div><div class="pr-bridge-label">Современное чтение</div><div class="pr-modern" lang="mn-Cyrl">${b.groups.map(g=>{const start=offset;offset+=g.text.length;const focussed=focus&&offset>focus[0]&&start<focus[1];return `<span class="pr-modern-group${selected!==null&&g.native.includes(selected)?' linked':''}${focussed?' focus':''}" style="${prGroupStyle(w,g)}" title="В записи: ${g.native.map(i=>nameOf(chars[i].ch)).join(' · ')}">${esc(g.text)}</span>`;}).join('')}</div>${meaning?`<p class="pr-meaning">${esc(meaning)}</p>`:''}${note?`<p class="pr-link-note">${esc(b.note)}</p>`:''}${selected!==null&&b.unmatched.includes(selected)?`<p class="pr-unmatched" role="status"><strong style="color:${colorOf(chars[selected].ch)}">${nameOf(chars[selected].ch)}</strong> есть в старой записи. Отдельной буквы для неё в современной подписи нет; читаем слово целиком.</p>`:''}</div>`;
}
// The user's comparison cards now show the coloured Cyrillic bridge directly.
vcCaseCard=function(c,i){
 const w=CONS_DATA.records[c.sample],b=PR.comparisons[c.id],key='compare-'+c.id,selected=prBridgeSelection[key]??null;
 return `<article class="vc-case pr-comparison"><div class="eyebrow">${['ПЕРВЫЙ СЛУЧАЙ','СРАВНИМ СО ВТОРЫМ','И С ТРЕТЬИМ'][i]}</div><h2>${esc(c.label)}</h2><div class="vc-native">${joinSvg(w,{color:true,selected:selected===null?-1:prChars(w)[selected].index,fontSize:94})}</div>${prBridge(w,b,key,selected,{meaning:c.gloss,focus:c.modernSpan})}<details class="vc-letter-detail"><summary>Правило и источник примера</summary><p>${esc(c.rule)}</p>${joinSource(w,'colour-'+vcState.family+'-'+i)}</details></article>`;
};
function prIndexScreen(){
 const stage=PR.stages[prState.stage],next=PR.cards.find(c=>prProgress.studied[c.id]!==c.version)||PR.cards[0];
 return sectionHeading('Читаем фразы','От двух знакомых слов к предложениям, короткому рассказу и первому фрагменту классического источника.','СЛЕДУЮЩИЙ ШАГ ПОСЛЕ БУКВ')+`<section class="pr-course-start"><div><span class="status-pill">Без таймера · в своём темпе</span><h2>Письмо → буквы → смысл</h2><p>У каждой письменной буквы свой цвет. Нажми на слово, затем на кириллическую подпись буквы: увидишь её место в цельной записи и объяснение.</p><p class="pr-progress">Разобрано: ${PR.cards.filter(c=>prProgress.studied[c.id]===c.version).length} / ${PR.cards.length} · Проверено самостоятельно: ${PR.cards.filter(c=>prProgress.clean[c.id]===c.version).length} / ${PR.cards.length}</p></div>${button('Продолжить чтение →','pr-open','primary',`data-id="${next.id}"`)}</section><div class="simple-fields"><label>Этап чтения<select id="pr-stage" aria-label="Этап чтения">${PR.stages.map((s,i)=>`<option value="${i}"${i===prState.stage?' selected':''}>${i+1}. ${s.title}</option>`).join('')}</select></label></div><p class="page-desc">${esc(stage.subtitle)}</p><div class="vc-family-list pr-reading-list">${PR.cards.filter(c=>c.stage===prState.stage).map(c=>`<button class="vc-family-row" data-action="pr-open" data-id="${c.id}"><span class="mono">${String(c.order).padStart(2,'0')}</span><div><strong>${esc(c.title)}</strong><p>${c.wordCount} ${c.wordCount===2?'слова':c.wordCount<5?'слова':'слов'} · ${c.kind==='source-fragment'?'фрагмент из источника':c.kind==='authored-microtext'?'учебный микротекст':'учебная фраза'}</p></div><span>${prProgress.clean[c.id]===c.version?'Самостоятельно ✓':prProgress.studied[c.id]===c.version?'Разобрано ✓':'Открыть'}</span><b aria-hidden="true">→</b></button>`).join('')}</div><details class="simple-details"><summary>Как устроен маршрут и откуда тексты</summary><p>${esc(PR.authorship)}</p><p>Здесь 18 коротких фраз, 3 учебных микротекста и 2 небольших фрагмента книжного названия. Это начало пути к классическим текстам; полноценные отрывки, новые жанры и дальнейшую грамматику будем добавлять следующим этапом.</p><p>«Разобрано» отмечает чтение с пояснениями. Самостоятельный результат сохраняется только после верного ответа без помощи и ошибок. Повторное открытие само по себе ничего не засчитывает.</p><p><a id="phrases-source-book" href="${PR.sources.book}#page=24" target="_blank" rel="noopener noreferrer">Пособие О. Ф. Золтоевой · окончания</a> · <a id="phrases-source-catalog" href="${PR.sources.catalog}#page=24" target="_blank" rel="noopener noreferrer">Каталог Л. С. Пучковского · с. 23</a></p></details>`;
}
function prLetterExplanation(w,ordinal){
 const chars=prChars(w),c=chars[ordinal]||chars[0],key=Object.keys(COURSE_INFO).find(k=>COURSE_INFO[k].native===c.ch),t=TEACHING.letters[key];
 const component=w.allLetters?.find(x=>x.index===c.index)?.g;
 const left=chars[ordinal-1],right=chars[ordinal+1],joinLeft=left&&!/[\s\u180e]/.test(w.text.slice(left.index+1,c.index)),joinRight=right&&!/[\s\u180e]/.test(w.text.slice(c.index+1,right.index));
 const position=joinLeft?(joinRight?'medial':'final'):(joinRight?'initial':'isolated');
 const fs=COURSES[key]?.bank.forms||[],matches=fs.filter(f=>f.glyph===component),f=matches.find(f=>f.position===position)||matches[0],form=t?.forms[f?.id];
 return `<section class="pr-letter-explanation"><h3>Письменная <span style="color:${colorOf(c.ch)}">${nameOf(c.ch)}</span> · место ${ordinal+1}</h3><p>${esc(form?.rule||t?.main||'Сохраняем знак в его окружении и читаем написание сверху вниз.')}</p>${t?.sound?`<p class="rule-small">${esc(t.sound)}</p>`:''}${key?`<a id="phrase-letter-course-${w.id}-${ordinal}" href="#${CONSONANT_IDS.includes(key)?'consonants':'vowels'}/${key}">Все формы ${nameOf(c.ch)} →</a>`:''}</section>`;
}
function prNativeLines(c,reveal){
 let n=0;return `<div class="pr-native-lines${c.lines.length>1?' multiple':''}" aria-label="Читаем слова вниз по колонке, следующую колонку справа">${c.lines.map((line,j)=>`<div class="pr-native-column"><span class="pr-column-direction">${c.lines.length>1?'Колонка '+(j+1):'Читаем'} ↓</span>${line.map(id=>{const index=n++,w=PR.words[id],selected=index===prState.word;return `<button class="pr-word${selected?' active':''}" data-action="pr-word" data-word="${index}" aria-label="Слово ${index+1}" aria-pressed="${selected}"><span class="pr-word-number">${index+1}</span>${joinSvg(w,{color:reveal,hits:reveal,selected:reveal&&selected?prChars(w)[prState.letter]?.index??-1:-1,fontSize:c.lines.length>1?48:60})}</button>`;}).join('')}${c.sentence||c.kind==='authored-microtext'?`<span class="pr-stop" aria-label="Монгольская точка">${joinSvg(PR.punctuation,{color:false,fontSize:36})}</span>`:''}</div>`).join('')}</div>`;
}
function prWholeModern(c){return c.lines.map(line=>line.map(k=>PR.words[k].modern).join(' ')).join('. ')+(c.sentence||c.kind==='authored-microtext'?'.':'');}
function prRulePanel(c){return `<section class="pr-rules"><h2>Почему читаем и понимаем так</h2>${c.rules.map((id,i)=>{const r=PR.rules[id];return `<article><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p>${r.lesson?`<a id="phrase-rule-${c.id}-${i}" href="${r.lesson}">Связанный мини-урок: ${esc(ruleById(r.lesson.split('/')[1])?.title||'правило чтения')} →</a>`:''}</article>`;}).join('')}</section>`;}
function prProvenance(c){return `<details class="simple-details"><summary>${c.kind==='source-fragment'?'Источник фрагмента':'Откуда взяты слова и правила'}</summary>${c.source?`<p><a id="phrase-original-${c.id}" href="${c.source.url}" target="_blank" rel="noopener noreferrer">${esc(c.source.name)} · ${esc(c.source.page)}</a></p><p>${esc(c.source.note)}</p>`:`<p>Фраза и русский перевод составлены для тренажёра. Словарные написания и правила образования форм имеют источники; это не историческая цитата.</p><p><a id="phrase-grammar-${c.id}" href="${PR.sources.book}#page=${PR.rules[c.rules.find(k=>PR.rules[k].page)||'past'].page}" target="_blank" rel="noopener noreferrer">О. Ф. Золтоева · правило словоформы</a></p>`}<ul>${[...new Set(prWords(c))].map((id,i)=>{const w=PR.words[id];return `<li><a id="phrase-lemma-${c.id}-${i}" href="${esc(w.source.url)}" target="_blank" rel="noopener noreferrer">${esc(w.latin)} · ${esc(w.source.name)}${w.source.page?' · '+esc(w.source.page):''}</a>${w.kind==='authored-wordform'?' — составленная словоформа':''}</li>`;}).join('')}</ul></details>`;}
function prReader(){
 const c=prCard(),guided=prState.mode==='guided',reveal=guided||prState.revealed,w=prWord(),count=prWords(c).length;
 return sectionHeading((c.kind==='source-fragment'?'Фрагмент':'Чтение')+' '+String(c.order).padStart(2,'0'),PR.stages[c.stage].title,'ЧИТАЕМ С РАЗБОРОМ')+`<div class="pr-reader-top"><a id="phrase-back" href="#phrases/stage/${c.stage}">← К списку чтений</a><label>Режим<select id="pr-mode" aria-label="Режим чтения"><option value="guided"${guided?' selected':''}>С цветом и разбором</option><option value="blind"${!guided?' selected':''}>Самостоятельно</option></select></label></div><p class="pr-reading-instruction">${reveal?'Читай вниз. Нажми на слово, затем на цветную кириллическую подпись нужной буквы.':'Прочитай запись без цвета и выбери перевод. Разбор можно открыть в любой момент.'}</p><div class="workspace pr-workspace"><section class="script-card pr-script"><div class="script-top"><span>${c.kind==='source-fragment'?'Фрагмент источника':c.kind==='authored-microtext'?'Учебный микротекст':'Учебная фраза'}</span><span>${count} ${count<5?'слова':'слов'}</span></div>${prNativeLines(c,reveal)}<div class="script-bottom"><span>↓ Сверху вниз</span><span>${c.lines.length>1?'Следующая колонка справа':'Пробел разделяет слова'}</span></div></section><section class="panel pr-analysis">${reveal?`<div class="eyebrow">СЛОВО ${prState.word+1} / ${count}</div><h2>Каждая буква связана с цветом</h2>${prBridge(w,w.bridge,'phrase-word',prState.letter,{meaning:w.ru})}${prLetterExplanation(w,prState.letter)}<details class="pr-transcription"><summary>Условная передача письменного слова</summary><p>${esc(w.latin)}</p><p>Она помогает увидеть состав старой записи. Современное чтение показано отдельно.</p></details>`:''}${!guided?`<section class="pr-comprehension"><h2>Что здесь сказано?</h2><div class="rule-answer-list" role="group" aria-label="Переводы для выбора">${c.question.options.map((a,i)=>button(esc(a),'pr-answer','rule-answer'+(prState.done&&i===c.question.answer?' correct':''),`data-index="${i}"${prState.done?' disabled':''}`)).join('')}</div>${prState.wrong?'<p class="feedback error" role="status">Пока не совпало. Сравни участника, действие и окончания. Этот пример останется для самостоятельного повторения.</p>':''}${prState.done?`<p class="feedback correct" role="status">Верно. ${prState.assisted?'Ответ после помощи или ошибки; самостоятельный результат не увеличен.':'Чтение засчитано в самостоятельный результат.'}</p>`:''}${!reveal?button('Открыть цвет и разбор','pr-help','hint'):''}${prState.assisted?'<p class="callout">Помощь или ошибка уже были: этот ответ не считается самостоятельным.</p>':''}</section>`:''}<p class="rule-small">${guided?'Нажатие отмечает разбор фразы. Самостоятельное чтение проверяется в другом режиме.':'Результат без помощи и ошибок хранится отдельно от разбора с цветом.'}</p>${prSaveError?'<p role="status">Браузер не сохранил результат. Он доступен в текущей вкладке.</p>':''}</section></div>${reveal?`<section class="pr-translation"><div class="eyebrow">СОБЕРЁМ СМЫСЛ</div><h2>Перевод всей ${c.kind==='authored-microtext'?'записи':'фразы'}</h2><p>${esc(c.translation)}</p><details><summary>Современная кириллическая передача целиком</summary><p lang="mn-Cyrl">${esc(prWholeModern(c))}</p></details></section>${prRulePanel(c)}${prProvenance(c)}`:''}<div class="pr-bottom"><div><span class="eyebrow">ЧТЕНИЕ ${c.order} / ${PR.cards.length}</span><p class="rule-small">${guided?'Отметим, что фраза разобрана с пояснениями.':'Результат без помощи и ошибок учитывается отдельно.'}</p></div>${button(c.order===PR.cards.length?'Завершить этот маршрут →':'Прочитано, дальше →','pr-next','primary',!guided&&!prState.done?'disabled':'')}</div>`;
}
function prAction(e){
 const b=e.target.closest('button[data-action]');if(!b||b.disabled||!b.dataset.action.startsWith('pr-'))return false;const a=b.dataset.action;
 if(a==='pr-open')prOpen(b.dataset.id,'guided');
 if(a==='pr-word'){
  const n=Number(b.dataset.word);if(Number.isInteger(n)&&n>=0&&n<prWords(prCard()).length){prState.word=n;prState.letter=0;const hit=e.target.closest('[data-letter-index]');if(hit&&(prState.mode==='guided'||prState.revealed)){const ordinal=prChars(prWord()).findIndex(c=>c.index===Number(hit.dataset.letterIndex));if(ordinal>=0)prState.letter=ordinal;}}
 }
 if(a==='pr-letter'){
  const i=Number(b.dataset.index);
  if(b.dataset.key==='phrase-word'){if(i>=0&&i<prChars(prWord()).length)prState.letter=i;}
  else if(b.dataset.key?.startsWith('compare-')){const id=b.dataset.key.slice(8),c=vcFamily().cases.find(c=>c.id===id);if(c&&i>=0&&i<prChars(CONS_DATA.records[c.sample]).length)prBridgeSelection[b.dataset.key]=i;}
 }
 if(a==='pr-answer')prAnswer(Number(b.dataset.index));
 if(a==='pr-help')prHelp();if(a==='pr-next')prNext();
 syncSiteRoute();render();if(['pr-open','pr-next'].includes(a))window.scrollTo({top:0,behavior:'instant'});return true;
}
function prSelect(e){if(e.target.id==='pr-stage'){prIndex(e.target.value);syncSiteRoute();render();return true;}if(e.target.id==='pr-mode'){prOpen(prState.id,e.target.value);syncSiteRoute();render();return true;}return false;}
const prPreviousApply=applySiteLocation;
applySiteLocation=function(){const p=location.hash.slice(1).split('/');if(p[0]==='phrases'){if(p[1]==='stage')prIndex(p[2]);else if(PR.cards.some(c=>c.id===p[1]))prOpen(p[1],p[2]);else prIndex();state.route=location.hash;return;}prPreviousApply();};
const prPreviousHash=siteHash;
siteHash=function(){if(state.section==='phrases')return state.screen==='phrase-reader'?'#phrases/'+prState.id+'/'+prState.mode:'#phrases'+(prState.stage?'/stage/'+prState.stage:'');return prPreviousHash();};
const prPreviousNavigate=navigateSection;
navigateSection=function(section){if(section==='phrases'){prIndex();return;}prPreviousNavigate(section);};
const prPreviousContent=siteContent;
siteContent=function(){if(state.section==='phrases')return state.screen==='phrase-reader'?prReader():prIndexScreen();return prPreviousContent();};
const prPreviousHome=homeScreen;
homeScreen=function(){return prPreviousHome().replace('href="#rules"><span>03</span><div><h3>Понимаем классическую запись</h3><p>36 коротких уроков: правила, окончания и первая строка с разбором.</p>','href="#phrases"><span>03</span><div><h3>Читаем фразы и первые тексты</h3><p>От двух слов к связному чтению: цвет каждой буквы, перевод и объяснения.</p>');};
const prPreviousMap=ruleMap;
ruleMap=function(){return prPreviousMap().replace('Следующий этап — связные классические тексты с нарастающей сложностью, словарь и дальнейшая грамматика.','В разделе «Читаем фразы» уже есть первые короткие фразы, микротексты и фрагменты названия из источника. Следующий этап — более длинные классические отрывки, словарь и дальнейшая грамматика.');};
const prLineLesson=ruleById('first-classical-line');if(prLineLesson)prLineLesson.practice='#phrases/bi-irebe/guided';

// A small navigation shell around the existing course. Bank IDs and progress
// namespaces are intentionally unchanged; dialogues have their own namespace.
const DL=DIALOGUE_DATA,DL_KEY='mongol-short-dialogues-v1';
Object.assign(CONS_DATA.font.glyphs,DL.font.glyphs);
Object.assign(CONS_DATA.font.ligatureCarets,DL.font.ligatureCarets);
Object.assign(PR.words,DL.words);
Object.assign(SITE_SECTIONS,{phrases:'Фразы и тексты',dialogues:'Диалоги'});
let dlSaveError=false,dlProgress;
try{const p=JSON.parse(localStorage.getItem(DL_KEY)||'{}');dlProgress={studied:p?.studied&&typeof p.studied==='object'&&!Array.isArray(p.studied)?p.studied:{},clean:p?.clean&&typeof p.clean==='object'&&!Array.isArray(p.clean)?p.clean:{}};}catch{dlProgress={studied:{},clean:{}};}
const dlState={id:DL.dialogs[0].id,mode:'guided',word:0,letter:0,revealed:false,assisted:false,done:false,wrong:false};
const dlCard=()=>DL.dialogs.find(c=>c.id===dlState.id)||DL.dialogs[0];
const dlWords=c=>c.turns.flatMap(t=>t.words);
const dlWord=()=>{const id=dlWords(dlCard())[dlState.word]||dlWords(dlCard())[0],w=PR.words[id];return id==='sain'?{...w,ru:'хорошо — оценка сказанного в этой реплике'}:w;};
function dlOpen(id=DL.dialogs[0].id,mode='guided'){
 arcLeave();const c=DL.dialogs.find(c=>c.id===id)||DL.dialogs[0];delete dlState.finished;Object.assign(dlState,{id:c.id,mode:mode==='blind'?'blind':'guided',word:0,letter:0,revealed:false,assisted:false,done:false,wrong:false});
 state.section='dialogues';state.screen='dialogue-reader';state.ruleId=null;
}
function dlMark(kind){dlProgress[kind][dlCard().id]=dlCard().version;try{localStorage.setItem(DL_KEY,JSON.stringify(dlProgress));dlSaveError=false;}catch{dlSaveError=true;}}
function dlHelp(){if(dlState.mode==='blind'&&!dlState.done){dlState.revealed=true;dlState.assisted=true;dlState.wrong=false;}}
function dlAnswer(n){
 if(state.section!=='dialogues'||dlState.mode!=='blind'||dlState.done||!Number.isInteger(n)||n<0||n>2)return;
 if(n!==dlCard().question.answer){dlState.assisted=true;dlState.wrong=true;return;}
 dlState.done=true;dlState.revealed=true;dlState.wrong=false;if(!dlState.assisted)dlMark('clean');
}
function dlNext(){if(dlState.mode==='blind'&&!dlState.done)return;const c=dlCard();dlMark('studied');const next=DL.dialogs[c.order];if(next)dlOpen(next.id,dlState.mode);else dlState.finished=true;}
function nuOptions(items,value){return items.map(([id,title])=>`<option value="${esc(String(id))}"${String(id)===String(value)?' selected':''}>${esc(title)}</option>`).join('');}
function nuSelect(id,label,options){return `<label class="nu-field">${label}<select id="${id}" aria-label="${label}">${options}</select></label>`;}
function nuModes(id,value){return nuSelect(id,'Подсказки',nuOptions([['guided','С цветом'],['blind','Без подсказок']],value));}
function nuTitle(title){return `<h1 class="nu-title">${esc(title)}</h1>`;}
function nuSummary(html){return `<details class="nu-details"><summary>Разбор</summary><div>${html}</div></details>`;}
function nuSourceLink(w,id){return w?.source?.url?`<a id="${id}" href="${esc(w.source.url)}" target="_blank" rel="noopener noreferrer">${esc(w.source.name)}${w.source.page?' · '+esc(w.source.page):''}</a>`:'';}
function nuBridge(w,b,key,selected=0,action='pr-letter'){
 const chars=prChars(w);
 return `<div class="nu-bridge" data-bridge="${esc(key)}"><span class="nu-caption">Буквы в записи ↓</span><div class="pr-letter-row" role="group" aria-label="Кириллические подписи письменных букв">${chars.map((c,i)=>button(`<small>${i+1}</small><strong style="color:${colorOf(c.ch)}">${nameOf(c.ch)}</strong>`,action,'pr-letter'+(i===selected?' selected':''),`data-key="${esc(key)}" data-index="${i}" aria-label="Письменная ${nameOf(c.ch)}, место ${i+1}" aria-pressed="${i===selected}"`)).join('')}</div><span class="nu-caption">Современное чтение</span><p class="nu-modern" lang="mn-Cyrl">${b.groups.map(g=>`<span class="pr-modern-group${g.native.includes(selected)?' linked':''}" style="${prGroupStyle(w,g)}" title="В записи: ${g.native.map(i=>nameOf(chars[i].ch)).join(' · ')}">${esc(g.text)}</span>`).join('')}</p><p class="nu-word-meaning">${esc(w.ru||'')}</p></div>`;
}
function nuModernWords(ids){return ids.map(k=>{const w=PR.words[k];return `<span class="nu-modern-word">${w.bridge.groups.map(g=>`<span style="${prGroupStyle(w,g)}">${esc(g.text)}</span>`).join('')}</span>`;}).join(' ');}
function dlNative(c,reveal){let n=0;return `<div class="nu-dialogue-columns" aria-label="Реплики читаем сверху вниз, следующая реплика справа">${c.turns.map((t,j)=>`<div class="nu-turn"><span class="nu-speaker">${t.speaker}<small>${j+1}</small></span><div class="nu-turn-words">${t.words.map(k=>{const i=n++,w=PR.words[k],selected=dlState.word===i;return `<button class="pr-word${selected?' active':''}" data-action="dl-word" data-word="${i}" aria-label="Реплика ${j+1}, слово ${t.words.indexOf(k)+1}" aria-pressed="${selected}">${joinSvg(w,{color:reveal,hits:reveal,selected:reveal&&selected?prChars(w)[dlState.letter]?.index??-1:-1,fontSize:c.turns.length===2?48:40})}</button>`;}).join('')}<span class="nu-punctuation" aria-label="${t.question?'Вопросительный знак':'Конец предложения'}">${t.question?'?':joinSvg(PR.punctuation,{color:false,fontSize:26})}</span></div></div>`).join('')}</div>`;}
function dlRules(c){return c.rules.map(id=>{const r=DL.rules[id];return `<article class="nu-rule"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p>${r.lesson&&ruleById(r.lesson.split('/')[1])?`<a id="dl-rule-${c.id}-${id}" href="${r.lesson}">Мини-урок</a>`:''}</article>`;}).join('');}
function dlSources(c){return `<details class="nu-sources"><summary>Источники</summary><p>${esc(DL.authorship)}</p><p><a id="dl-grammar-${c.id}" href="${DL.sources.book}#page=7" target="_blank" rel="noopener noreferrer">О. Ф. Золтоева · вопросительные предложения, PDF 7</a></p><ul>${[...new Set(dlWords(c))].map((k,i)=>`<li>${esc(PR.words[k].latin)} — ${nuSourceLink(PR.words[k],'dl-source-'+c.id+'-'+i)}</li>`).join('')}</ul><p>Вопросительный знак — современная учебная пунктуация. Вертикальный текст набран заново; это не факсимиле.</p><a id="dl-punctuation-${c.id}" href="${DL.sources.unicode}" target="_blank" rel="noopener noreferrer">Unicode · монгольское письмо и пунктуация</a></details>`;}
function nuReadingToolbar(kind,cards,current,mode,groups){return `<div class="nu-toolbar">${nuSelect('nu-'+kind,'Задание',groups.map((g,i)=>`<optgroup label="${esc(g.title)}">${cards.filter(c=>c.stage===i).map(c=>`<option value="${c.id}"${c.id===current?' selected':''}>${kind==='dialogue'?'Диалог':'Чтение'} ${c.order}${mode==='guided'?' · '+esc(c.title):''}</option>`).join('')}</optgroup>`).join(''))}${nuModes('nu-'+kind+'-mode',mode)}</div>`;}
function dlReader(){
 const c=dlCard(),guided=dlState.mode==='guided',reveal=guided||dlState.revealed,w=dlWord();
 return dialogueMasthead(nuTitle('Диалоги'),nuReadingToolbar('dialogue',DL.dialogs,c.id,dlState.mode,DL.stages))+`<div class="nu-reading-layout"><section class="nu-page-script">${dlNative(c,reveal)}<p class="nu-caption">↓ Сверху вниз · реплики слева направо</p></section><section class="nu-reading-side">${reveal?`<div class="nu-translations">${c.turns.map((t,i)=>`<div class="nu-translation"><span>${t.speaker}</span><div><p class="nu-turn-modern" lang="mn-Cyrl">${dialogueReadingPunctuation(t)}${t.question?'?':'.'}</p><p>${esc(t.translation)}</p></div></div>`).join('')}</div>${nuBridge(w,w.bridge,'dialogue-word',dlState.letter,'dl-letter')}`:''}${!guided?`<section class="nu-check"><h2>${esc(c.question.prompt)}</h2><div class="rule-answer-list" role="group" aria-label="Смысл разговора">${c.question.options.map((a,i)=>button(esc(a),'dl-answer','rule-answer'+(dlState.done&&i===c.question.answer?' correct':''),`data-index="${i}"${dlState.done?' disabled':''}`)).join('')}</div>${dlState.wrong?'<p class="feedback error" role="status">Пока не так. Попробуйте ещё раз.</p>':''}${dlState.done?`<p class="feedback correct" role="status">Верно.${dlState.assisted?' После помощи или ошибки.':' Самостоятельно ✓'}</p>`:''}${!reveal?button('Подсказка','dl-help','nu-help'):''}</section>`:''}</section></div>${reveal?nuSummary(`${prLetterExplanation(w,dlState.letter)}${dlRules(c)}<p>${esc(DL.rules.turns.text)}</p>${dlSources(c)}`):''}<div class="nu-bottom">${dlState.finished?'<p role="status">Все 12 диалогов пройдены. Для повторения выберите диалог в списке.</p>':button(c.order===DL.dialogs.length?'Завершить':'Дальше','dl-next','primary',!guided&&!dlState.done?'disabled':'')}<span class="nu-caption">${c.order} / ${DL.dialogs.length}${dlProgress.clean[c.id]===c.version?' · самостоятельно ✓':dlProgress.studied[c.id]===c.version?' · разобрано ✓':''}</span></div>${dlSaveError?'<p role="status">Не удалось сохранить результат в браузере.</p>':''}`;
}
function dlAction(e){
 const b=e.target.closest('button[data-action]');if(!b||b.disabled||!b.dataset.action.startsWith('dl-'))return false;
 const a=b.dataset.action;if(a==='dl-word'){const n=Number(b.dataset.word);if(Number.isInteger(n)&&n>=0&&n<dlWords(dlCard()).length){dlState.word=n;dlState.letter=0;const hit=e.target.closest('[data-letter-index]');if(hit&&(dlState.mode==='guided'||dlState.revealed)){const j=prChars(dlWord()).findIndex(c=>c.index===Number(hit.dataset.letterIndex));if(j>=0)dlState.letter=j;}}}
 if(a==='dl-letter'){const n=Number(b.dataset.index);if(Number.isInteger(n)&&n>=0&&n<prChars(dlWord()).length)dlState.letter=n;}
 if(a==='dl-help')dlHelp();if(a==='dl-answer')dlAnswer(Number(b.dataset.index));if(a==='dl-next')dlNext();syncSiteRoute();render();if(a==='dl-next')window.scrollTo({top:0,behavior:'instant'});return true;
}
// Only the navigation shell changes. All practice and grading handlers remain.
siteHeader=function(){return `<aside class="nu-rail"><details class="nu-menu"><summary aria-label="Меню"><span class="nu-hamburger" aria-hidden="true"></span><span class="nu-menu-word">Меню</span></summary><nav aria-label="Меню тренажёра"><a id="nu-home" href="#home">Главная</a><details open><summary>Буквы</summary><a id="nu-vowels" href="#vowels">Гласные</a><a id="nu-consonants" href="#consonants">Согласные</a><a id="nu-alphabet" href="#alphabet">Весь алфавит</a><a id="nu-combinations" href="#combinations">Сочетания</a></details><details open><summary>Чтение</summary><a id="nu-phrases" href="#phrases">Фразы и тексты</a><a id="nu-dialogues" href="#dialogues">Диалоги</a></details><a id="nu-rules" href="#rules">Правила чтения</a><a id="nu-games" href="#games">Игры</a></nav></details></aside><header class="nu-header"><a id="nu-brand" href="#home">Монгол бичиг</a>${['vowels','consonants'].includes(state.section)?nuSelect('nu-letter','Буква',`<optgroup label="Гласные">${nuOptions(VOWEL_IDS.map(k=>[k,COURSE_INFO[k].letter+(k==='x1827'?' · дополнительная':'')]),state.letter)}</optgroup><optgroup label="Согласные">${nuOptions(CONSONANT_IDS.map(k=>[k,COURSE_INFO[k].letter]),state.letter)}</optgroup>`):''}</header>`;};
sectionHeading=function(title){return nuTitle(title);};
pageIntro=function(title){return nuTitle(title);};
homeScreen=function(){return nuTitle('Монгольское письмо')+`<p class="nu-lead">Учимся читать: от первой буквы до коротких текстов.</p><div class="nu-home-form">${nuSelect('nu-home-section','Раздел',nuOptions([['vowels','Гласные'],['consonants','Согласные'],['combinations','Сочетания'],['phrases','Фразы и тексты'],['dialogues','Диалоги'],['rules','Правила чтения'],['games','Игры']],'vowels'))}${button('Начать','nu-home-start','primary')}</div>`;};
function nuFormSelect(){return nuSelect('nu-form','Форма',nuOptions([['intro','Знакомство с буквой'],...BANK.forms.map(f=>[f.id,f.title])],state.screen==='letter'?'intro':state.form));}
letterIntro=function(){const c=course(),t=teachingInfo(),f=BANK.forms.find(f=>f.id==='isolated')||BANK.forms[0],w=FONT_DATA.samples[c.native];return nuTitle('Буква '+c.letter)+nuFormSelect()+`<div class="nu-letter-layout"><section class="nu-letter-model">${wordSvg(w,{color:true,large:true})}<strong style="color:${c.color}">${c.letter}</strong></section><section><p class="nu-rule-main">${esc(t.sound)}</p><p>${esc(t.main)}</p>${button('Изучить первую форму','form','primary',`data-form="${f.id}"`)}</section></div>`+nuSummary(`<p>${esc(t.readingReminder)}</p><!-- letter notes 0 omitted -->`);};
catalogScreen=function(){return formIntro();};
teachingWordPanel=function(w,f){const token=state.letter+'/'+f.id;if(teachingState.token!==token){teachingState.token=token;teachingState.selected=teachingFocus(w,f);}const bridge=Object.values(PR.words).find(x=>x.text===w.text&&x.modern===w.modern)?.bridge;return `<section class="nu-teaching-word"><div class="nu-word-model">${wordSvg(w,{color:true,selected:teachingState.selected,large:true})}</div><span class="nu-caption">Буквы в записи ↓</span><div class="teach-letter-row" role="group" aria-label="Разобрать буквы примера">${visibleChars(w).map((c,i)=>button(`<small>${i+1}</small><strong style="color:${colorOf(c.ch)}">${nameOf(c.ch)}</strong>`,'teach-letter','teach-letter'+(c.index===teachingState.selected?' active':''),`data-index="${c.index}" aria-label="Разобрать букву ${nameOf(c.ch)}, место ${i+1}" aria-pressed="${c.index===teachingState.selected}"`)).join('')}</div>${w.modern?`<span class="nu-caption">Современное чтение</span><p class="nu-modern" lang="mn-Cyrl">${bridge?bridge.groups.map(g=>`<span style="${prGroupStyle(w,g)}">${esc(g.text)}</span>`).join(''):esc(w.modern)}</p>${wordAuditRussianLine(w)}`:wordAuditMissingCyrillic(w,w.kind==='alphabet-example'?'Учебный образец формы':'Образец написания')}</section>`;};
formIntro=function(){const f=F(),w=teachingSample(f),t=teachingFormInfo();return nuTitle('Буква '+course().letter)+nuFormSelect()+`<div class="nu-letter-layout">${teachingWordPanel(w,f)}<section><p class="nu-rule-main">${esc(t.rule)}</p>${nuModes('simple-practice-mode',simpleMode)}${button('Тренироваться','simple-form-start','primary')}<p class="nu-caption">С цветом: ${completed(f.id,'guided')} / 200 · без подсказок: ${completed(f.id,'blind')} / 300</p></section></div>`+nuSummary(`<p>${esc(teachingInfo().sound)}</p><ol>${t.steps.slice(1).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>${esc(teachingInfo().readingReminder)}</p><!-- letter notes 1 omitted -->`);};
// Entry pages open a single lesson instead of walls of letter/form cards.
vowelsScreen=()=>letterIntro();consonantsScreen=()=>letterIntro();
let nuGame='assemble',nuHomeSection='vowels',nuRuleId=READING_RULES.lessons.find(l=>!ruleIsComplete(l))?.id||READING_RULES.lessons[0].id;
newGamesScreen=function(){const mixed=arcadeSettings.letter==='mixed',g=ARCADE_GAMES[nuGame],selected=mixed?'group:'+arcadeSettings.group:arcadeSettings.letter;arcUse(mixed?arcScopeLetters(arcadeSettings.group)[0]:arcadeSettings.letter,arcadeSettings.form);return nuTitle('Игры')+`<div class="nu-game-form">${nuSelect('nu-game','Игра',nuOptions(Object.entries(ARCADE_GAMES).map(([k,v])=>[k,v.title]),nuGame))}${nuSelect('nu-game-letters','Буквы',`<optgroup label="Вперемешку">${nuOptions([['group:vowels','Все гласные'],['group:consonants','Все согласные'],['group:all','Все буквы']],selected)}</optgroup><optgroup label="По одной букве">${nuOptions(Object.keys(ARCADE_INFO).map(k=>[k,ARCADE_INFO[k].letter]),selected)}</optgroup>`)}<p>${esc(g.description)}</p><details class="nu-settings"><summary>Настройки</summary>${nuModes('nu-game-mode',arcadeSettings.mode)}${nuSelect('nu-game-time','Таймер',nuOptions([[0,'Без таймера'],[30,'30 секунд'],[60,'60 секунд'],[120,'120 секунд']],arcadeSettings.seconds))}${!mixed?nuSelect('arcade-form','Форма',nuOptions(arcBank().forms.map(f=>[f.id,f.title]),arcContext.form)):''}</details>${button('Играть','arc-launch','primary',`data-game="${nuGame}"`)}</div>`;};
ruleIndex=function(){return nuTitle('Правила чтения')+`<div class="nu-rule-picker">${nuSelect('nu-rule','Урок',READING_RULES.groups.map((g,i)=>`<optgroup label="${esc(g.title)}">${nuOptions(READING_RULES.lessons.filter(l=>l.group===i).map(l=>[l.id,l.order+'. '+l.title+(ruleIsComplete(l)?' ✓':'')]),nuRuleId)}</optgroup>`).join(''))}${button('Открыть урок','nu-rule-open','primary')}<p class="nu-caption">Пройдено: ${ruleCompletedCount()} / ${READING_RULES.lessons.length}</p></div>`;};
const nuOldRuleLesson=ruleLesson;
ruleLesson=function(){const l=ruleById(ruleSession?.id);if(!l)return ruleIndex();const picker=nuSelect('nu-rule-current','Урок',nuOptions(READING_RULES.lessons.map(x=>[x.id,x.order+'. '+x.title]),l.id));if(ruleSession.phase!=='learn')return picker+nuOldRuleLesson().replace(/<div class="rule-lesson-nav">[\s\S]*?<\/div>/,'');return nuTitle(l.title)+picker+`<section class="nu-rule-lesson"><p class="nu-rule-main">${l.rule}</p><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="rule-examples">${l.examples.map(ruleExample).join('')}</div>${button('Проверить себя','rule-start','primary')}${nuSummary(ruleSourceNotes(l))}</section>`;};
function nuJoinSelect(){return nuSelect('nu-join','Сочетание',`<optgroup label="Сравнение гласных">${nuOptions([...VC.families,VC.extra].map(f=>['compare:'+f.id,f.title]),state.screen.startsWith('vc-')?'compare:'+vcState.family:'')}</optgroup>${Object.entries(JOIN_GROUPS).map(([group,title])=>`<optgroup label="${esc(title)}">${nuOptions(JOIN_UNITS.filter(u=>group==='reading'?['long','diphthong'].includes(u.group):u.group===group).map(u=>[u.id,u.label]),joinView.unit)}</optgroup>`).join('')}`);}
joinIndex=function(){const tab=joinView.tab,u=JOIN_UNITS.find(u=>(tab==='reading'?['long','diphthong'].includes(u.group):u.group===tab)&&(['cv','vc','cc'].includes(tab)?u.keys.includes(joinView.letter):tab==='vv'?u.keys[0]===joinView.vowel:true));if(u){joinView.unit=u.id;return joinIntro();}return nuTitle('Сочетания')+nuJoinSelect()+'<p>В словарном корпусе такого сочетания пока нет.</p>';};
joinIntro=function(){const u=joinUnit(),w=CONS_DATA.records[u.sample],b=Object.values(PR.words).find(x=>x.text===w.text&&x.modern===w.modern)?.bridge;return nuTitle('Сочетания')+nuJoinSelect()+`<div class="nu-letter-layout"><section class="nu-teaching-word"><div class="nu-word-model">${joinSvg(w,{color:true,large:true})}</div>${w.kind==='alphabet-example'?'<p class="nu-caption">Образец соединения букв</p>':''}<span class="nu-caption">Буквы в записи ↓</span><p class="nu-written-line">${visibleChars(w).map(c=>`<strong style="color:${colorOf(c.ch)}">${nameOf(c.ch)}</strong>`).join(' · ')}</p>${w.modern?`<span class="nu-caption">Современное чтение</span><p class="nu-modern">${b?b.groups.map(g=>`<span style="${prGroupStyle(w,g)}">${esc(g.text)}</span>`).join(''):esc(w.modern)}</p>${wordAuditRussianLine(w)}`:(w.kind==='dictionary'?wordAuditMissingCyrillic(w,''):'')}</section><section><p class="nu-rule-main">${esc(u.rule)}</p>${u.seq?'<p class="nu-join-example-guide">'+esc(joinExampleGuidance(u,w))+'</p>':''}${nuModes('simple-practice-mode',simpleMode)}${button('Тренироваться','simple-join-start','primary')}<p class="nu-caption">С цветом: ${joinDone(u,'guided')} / 200 · без подсказок: ${joinDone(u,'blind')} / 300</p></section></div>`+nuSummary(`${joinRuleDetail(u)}<ol>${u.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>${joinMaterial(u)}</p>${joinWordNotes(w,'compact')}${joinAmbiguity()}${joinCredits(u.id)}`);};
vcIndexScreen=function(){return vcFamilyScreen();};
vcFamilyScreen=function(){const f=vcFamily(),c=f.cases.find(c=>c.id===vcState.unit)||f.cases[0],u=VC.units[c.id];return nuTitle('Сочетания')+nuJoinSelect()+`<div class="vc-cases${f.cases.length===2?' two':''}">${f.cases.map(vcCaseCard).join('')}</div><div class="nu-toolbar">${nuSelect('vc-case','Что тренируем',nuOptions(f.cases.map(x=>[x.id,x.label]),c.id))}${nuModes('simple-practice-mode',simpleMode)}</div>${button('Тренироваться','vc-start','primary')}<p class="nu-caption">${u?`С цветом: ${vcDone(u,'guided')} / 200 · без подсказок: ${vcDone(u,'blind')} / 300`:'200 с цветом · 300 без подсказок'}</p>${nuSummary(`<p>${esc(f.note||'')}</p>${vcSources(f.id)}`)}`;};
vcCaseCard=function(c,i){const w=CONS_DATA.records[c.sample],b=PR.comparisons[c.id],key='compare-'+c.id,selected=prBridgeSelection[key]??null;return `<article class="vc-case"><h2>${esc(c.label)}</h2><div class="vc-native">${joinSvg(w,{color:true,selected:selected===null?-1:prChars(w)[selected].index,fontSize:66})}</div>${nuBridge({...w,ru:c.gloss},b,key,selected,'pr-letter',c.modernSpan)}<p class="nu-case-rule">${esc(c.rule)}</p></article>`;};
prIndexScreen=function(){return prReader();};
prReader=function(){const c=prCard(),guided=prState.mode==='guided',reveal=guided||prState.revealed,w=prWord();return nuTitle('Фразы и тексты')+nuReadingToolbar('phrase',PR.cards,c.id,prState.mode,PR.stages)+`<div class="nu-reading-layout"><section class="nu-page-script">${prNativeLines(c,reveal)}<p class="nu-caption">↓ Сверху вниз</p></section><section class="nu-reading-side">${reveal?`<p class="nu-phrase-modern" lang="mn-Cyrl">${c.lines.map(line=>nuModernWords(line)).join('. ')}${c.sentence?'.':''}</p><p class="nu-phrase-translation">${esc(c.translation)}</p>${nuBridge(w,w.bridge,'phrase-word',prState.letter)}`:''}${!guided?`<section class="nu-check"><h2>Выберите перевод</h2><div class="rule-answer-list" role="group" aria-label="Переводы для выбора">${c.question.options.map((a,i)=>button(esc(a),'pr-answer','rule-answer'+(prState.done&&i===c.question.answer?' correct':''),`data-index="${i}"${prState.done?' disabled':''}`)).join('')}</div>${prState.wrong?'<p class="feedback error" role="status">Пока не так. Попробуйте ещё раз.</p>':''}${prState.done?`<p class="feedback correct" role="status">Верно.${prState.assisted?' После помощи или ошибки.':' Самостоятельно ✓'}</p>`:''}${!reveal?button('Подсказка','pr-help','nu-help'):''}</section>`:''}</section></div>${reveal?nuSummary(`${prLetterExplanation(w,prState.letter)}${prRulePanel(c)}${prProvenance(c)}`):''}<div class="nu-bottom">${button(c.order===PR.cards.length?'Завершить':'Дальше','pr-next','primary',!guided&&!prState.done?'disabled':'')}<span class="nu-caption">${c.order} / ${PR.cards.length}${prProgress.clean[c.id]===c.version?' · самостоятельно ✓':prProgress.studied[c.id]===c.version?' · разобрано ✓':''}</span></div>`;};
// Unclutter practice without removing choices, feedback or learning content.
const nuOldExercise=exercise;
modeSwitch=function(){return nuModes('nu-letter-practice-mode',state.mode);};
exercise=function(){return nuOldExercise().replace(/<div class="reader-toolbar">[\s\S]*?<\/div>/,'').replace(/<div class="eyebrow">[^<]*<\/div>/g,'').replace(/<div class="lesson-bottom">[\s\S]*?<\/div>/,'').replace(/<button class="back" data-action="form-back"[^>]*>[\s\S]*?<\/button>/,'').replace(/<p class="small-label session-note">[\s\S]*?<\/p>/,'');};
const nuOldContent=siteContent;
siteContent=function(){if(state.section==='dialogues')return dlReader();return nuOldContent();};
const nuOldNavigate=navigateSection;
navigateSection=function(section){
 if(section==='dialogues'){const c=DL.dialogs.find(c=>dlProgress.studied[c.id]!==c.version)||DL.dialogs[0];dlOpen(c.id);return;}
 if(section==='phrases'){const c=PR.cards.find(c=>prProgress.studied[c.id]!==c.version)||PR.cards[0];prOpen(c.id);return;}
 if(['vowels','consonants'].includes(section)){arcLeave();chooseCourse(section==='vowels'?'a':'x1828','lesson');state.section=section;state.screen='letter';return;}
 if(section==='combinations'){vcOpen('a');return;}
 nuOldNavigate(section);
};
const nuOldHash=siteHash;
siteHash=function(){if(state.section==='dialogues')return '#dialogues/'+dlState.id+'/'+dlState.mode;return nuOldHash();};
const nuOldApply=applySiteLocation;
applySiteLocation=function(){const p=location.hash.slice(1).split('/');
 if(p[0]==='dialogues'){dlOpen(p[1],p[2]);state.route=location.hash;return;}
 if(p[0]==='phrases'&&(!p[1]||p[1]==='stage')){const c=PR.cards.find(c=>p[1]==='stage'?c.stage===Number(p[2]):prProgress.studied[c.id]!==c.version)||PR.cards[0];prOpen(c.id);state.route=location.hash;return;}
 if(p[0]==='combinations'&&!p[1]){vcOpen('a');state.route=location.hash;return;}
 nuOldApply();
};
function nuAction(e){const b=e.target.closest('button[data-action]');if(!b||b.disabled||!b.dataset.action.startsWith('nu-'))return false;if(b.dataset.action==='nu-home-start')navigateSection(nuHomeSection);if(b.dataset.action==='nu-rule-open')openRule(nuRuleId);syncSiteRoute();render();return true;}
function nuSelectAction(e){const id=e.target.id,v=e.target.value;
 if(id==='nu-home-section'){nuHomeSection=v;return true;}
 if(id==='nu-letter'){chooseCourse(v,'lesson');state.section=letterSection();state.screen='letter';}
 else if(id==='nu-letter-practice-mode')start(v==='blind'?'blind':'guided');
 else if(id==='nu-form'){if(v==='intro')state.screen='letter';else if(BANK.forms.some(f=>f.id===v)){state.form=v;state.screen='form';state.view='lesson';resetTask();}}
 else if(id==='nu-dialogue'){dlOpen(v,dlState.mode);delete dlState.finished;}
 else if(id==='nu-dialogue-mode'){dlOpen(dlState.id,v);delete dlState.finished;}
 else if(id==='nu-phrase')prOpen(v,prState.mode);
 else if(id==='nu-phrase-mode')prOpen(prState.id,v);
 else if(id==='nu-rule'){nuRuleId=v;return true;}
 else if(id==='nu-rule-current')openRule(v);
 else if(id==='nu-join'){if(v.startsWith('compare:'))vcOpen(v.slice(8));else joinOpen(v);}
 else if(id==='nu-game')nuGame=v;
 else if(id==='nu-game-letters'){if(v.startsWith('group:')){arcadeSettings.group=v.slice(6);arcadeSettings.letter='mixed';arcadeSettings.form='';}else if(ARCADE_INFO[v]){arcadeSettings.group=ARCADE_INFO[v].group;arcadeSettings.letter=v;arcUse(v);arcadeSettings.form=arcContext.form;}persistArcade();}
 else if(id==='nu-game-mode'){arcadeSettings.mode=v==='blind'?'blind':'guided';persistArcade();}
 else if(id==='nu-game-time'){arcadeSettings.seconds=[30,60,120].includes(Number(v))?Number(v):0;persistArcade();}
 else return false;
 syncSiteRoute();render();return true;
}

// Home-only model result; learning runtime and routes remain intact.
