const mgStyle=document.createElement("style");mgStyle.id="mongolian-interface-style";mgStyle.textContent=":root{--mg-paper:#F6F0E4;--mg-surface:#FFFCF5;--mg-blue:#23455E;--mg-ink:#263D48;--mg-red:#AB5942;--mg-gold:#B58C49;--mg-line:#DCCDB3}\nhtml,body{background:var(--mg-paper)!important;color:var(--mg-ink)!important}body{font-family:Arial,Helvetica,sans-serif!important}\n#app .nu-header{max-width:1160px;padding:25px 42px 20px 98px;min-height:86px;border-bottom:1px solid transparent}\n#app .nu-header>a{font-size:20px;font-weight:600;letter-spacing:-.025em;color:var(--mg-blue)}\n#app .nu-header>a:before{content:\"\";display:inline-block;width:11px;height:11px;transform:rotate(45deg);border:2px solid var(--mg-gold);margin-right:14px;box-shadow:inset 0 0 0 2px var(--mg-paper),inset 0 0 0 2px var(--mg-gold)}\n#app .nu-rail{width:54px;background:#EDE2CB;border-color:#D6C5A4}\n#app .nu-menu>summary{width:53px;height:68px}#app .nu-hamburger,#app .nu-hamburger:before,#app .nu-hamburger:after{background:var(--mg-blue)}\n#app .nu-menu[open]>summary .nu-hamburger{background:transparent}\n#app .nu-menu-word{left:16px;bottom:30px;font-size:12px;letter-spacing:.06em;color:var(--mg-blue)}\n#app .nu-menu>nav{left:54px;background:var(--mg-surface);border-color:var(--mg-line);box-shadow:8px 0 28px #23455E14;padding:35px 27px}\n#app .nu-menu>nav a{color:var(--mg-blue);padding:9px 0;font-size:15px}\n#app .nu-menu>nav details{border-color:var(--mg-line)}#app .nu-menu>nav details>summary{color:#766950;font-size:12px;letter-spacing:.02em}\n#app .site-main.main{max-width:1160px;padding:24px 42px 72px 98px}\n#app .nu-title{color:var(--mg-blue);font-size:30px!important;letter-spacing:-.025em!important}\n#app .nu-field{color:#746B5C;font-size:12px}\n#app .nu-field select,#app .site-main select{background:var(--mg-surface);border-color:#CDBF9F;border-radius:8px;color:var(--mg-ink);box-shadow:none}\n#app button.primary,#app .site-main .primary{background:var(--mg-blue)!important;border-color:var(--mg-blue)!important;border-radius:10px!important;color:#fff!important;padding:13px 30px;font-weight:600!important}\n#app button.primary:hover:not(:disabled){background:#315873!important;border-color:#315873!important}\n#app :is(button,a,select,summary):focus-visible{outline:3px solid #416F8B!important;outline-offset:4px}\n#app .nu-details{border-color:var(--mg-line)}#app .nu-details>summary{color:var(--mg-blue)}\n#app .nu-details a,#app .nu-sources a{color:#315873}\n#app .nu-page-script,#app .nu-translations,#app .nu-phrase-translation,#app .nu-teaching-word{border-color:var(--mg-line)}\n#app .nu-page-script .pr-word.active,#app .nu-bridge .pr-letter.selected,#app .nu-teaching-word .teach-letter.active{background:var(--mg-surface);border-color:#BAA579}\n#app .nu-bridge .pr-letter,#app .nu-teaching-word .teach-letter{background:#FFFCF599}\n#app .nu-caption{color:#726651}\n#app .nu-check .rule-answer{background:var(--mg-surface);border-color:var(--mg-line);border-radius:8px;color:var(--mg-ink)}\n#app .nu-check .rule-answer.correct{border-color:#53785B;background:#EEF3E7}\n#app .site-main :is(.script-card,.panel,.arc-play-card,.rule-check,.rule-explanation){background:#FFFCF599;border-color:var(--mg-line);border-radius:10px;box-shadow:none}\n#app .vc-case{border-color:var(--mg-line)!important}#app .vc-case .vc-native{background:#FFFCF599!important;border:1px solid #E8DDC8;border-radius:9px}\n.mg-home{width:100%;padding-bottom:15px}\n.mg-home-intro{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(240px,1fr);align-items:center;gap:42px;margin:10px 0 38px}\n.mg-home-copy{padding:8px 0 4px}.mg-intro-line{display:block;width:50px;height:3px;background:var(--mg-red);position:relative;margin:0 0 24px}.mg-intro-line:after{content:\"\";width:6px;height:6px;position:absolute;right:-12px;top:-2px;border:1px solid var(--mg-red);transform:rotate(45deg)}\n.mg-home h1{font:600 48px/1.1 Arial,Arial,Helvetica,sans-serif!important;letter-spacing:-.05em!important;color:var(--mg-blue)!important;margin:0 0 24px!important}\n.mg-home-copy>p{font-size:18px;line-height:1.7;color:#6C6254;margin:0;max-width:460px}\n.mg-ger-art{display:block;width:100%;height:auto;max-width:360px;justify-self:end}\n.mg-home-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:19px}\n.mg-home-tile{position:relative;display:flex;flex-direction:column;gap:28px;justify-content:space-between;min-height:230px;padding:26px 26px 28px;border:1px solid #D7C5A4;background:var(--mg-surface);border-radius:16px;text-decoration:none!important;overflow:hidden;box-shadow:0 4px 0 #C6B59814;transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}\n.mg-home-tile:hover{transform:translateY(-3px);box-shadow:0 10px 25px #23455E0E;border-color:#AD8C52}\n.mg-tile-top{display:flex;align-items:start;justify-content:space-between;gap:20px}\n.mg-tile-icon{width:47px;height:47px;display:block;color:var(--mg-red)}.mg-tile-icon svg{width:100%;height:100%;display:block}.mg-tile-icon .connected-word{height:48px!important;width:auto!important;max-width:47px;max-height:50px!important;display:block;margin:0 auto}\n.mg-tile-joins .mg-tile-icon,.mg-tile-phrases .mg-tile-icon{color:#497A7D}.mg-tile-rules .mg-tile-icon{color:#A7813E}.mg-tile-dialogues .mg-tile-icon,.mg-tile-games .mg-tile-icon{color:#47617C}\n.mg-tile-arrow{font:400 20px/1 Arial,sans-serif;color:#AB9A7F;margin-top:2px;transition:color .16s ease}\n.mg-home-tile:hover .mg-tile-arrow{color:var(--mg-blue)}\n.mg-home-tile h2{font:600 20px/1.3 Arial,Helvetica,sans-serif!important;letter-spacing:-.025em!important;color:var(--mg-blue)!important;margin:0 0 9px!important}\n.mg-home-tile p{font-size:13px;line-height:1.65;color:#75674F;margin:0;max-width:235px}\n.mg-tile-corner{position:absolute;right:-13px;bottom:-13px;width:45px;height:45px;border:1px solid #E8DAC0;transform:rotate(45deg)}.mg-tile-corner:before{content:\"\";position:absolute;inset:6px;border:1px solid #E8DAC0}\n.mg-tile-letters{border-top:3px solid #AB5942;padding-top:21px}.mg-tile-dialogues{background:#F0F2EA}\n@media(min-width:1500px){#app .site-main.main{padding-top:38px}.mg-home-intro{margin-bottom:44px}.mg-home-grid{gap:22px}.mg-home-tile{min-height:225px}}\n@media(max-width:960px){#app .nu-header{padding-left:83px;padding-right:28px}#app .site-main.main{padding-left:83px;padding-right:28px}.mg-home-intro{gap:25px;grid-template-columns:minmax(0,1.35fr) minmax(220px,1fr)}.mg-home h1{font-size:36px!important}.mg-home-copy>p{font-size:15px}.mg-home-grid{gap:15px}.mg-home-tile{padding:20px;min-height:220px}.mg-tile-letters{padding-top:18px}.mg-home-tile h2{font-size:19px!important}.mg-home-tile p{font-size:12px}}\n@media(max-width:760px){.mg-home-intro{grid-template-columns:minmax(0,1fr) 170px;gap:20px;margin:5px 0 28px}.mg-home h1{font-size:30px!important}.mg-home-copy>p{font-size:14px}.mg-wide-break{display:none}.mg-intro-line{margin-bottom:18px}.mg-home-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.mg-home-tile{min-height:200px}.mg-home-tile h2{font-size:19px!important}.mg-home-tile p{font-size:13px}}\n@media(max-width:540px){#app .nu-rail{width:43px}#app .nu-menu>summary{width:42px;height:61px}#app .nu-menu>nav{left:43px;max-width:calc(100vw - 43px)}#app .nu-menu-word{left:11px;bottom:25px}#app .nu-header{padding:17px 20px 14px 63px;min-height:72px;gap:12px}#app .nu-header>a{font-size:15px}#app .nu-header>a:before{width:8px;height:8px;border-width:1px;margin-right:10px}#app .site-main.main{padding:20px 20px 45px 63px}#app .nu-header>.nu-field{max-width:115px}#app .nu-title{font-size:25px!important}.mg-home-intro{grid-template-columns:1fr;gap:23px;margin:4px 0 24px}.mg-home h1{font-size:32px!important;line-height:1.16!important;margin-bottom:16px!important}.mg-home-copy>p{font-size:14px}.mg-ger-art{width:100%;max-width:none;max-height:160px;object-fit:cover;object-position:center}.mg-home-grid{grid-template-columns:1fr;gap:14px}.mg-home-tile{display:grid;grid-template-columns:46px minmax(0,1fr);align-items:center;column-gap:19px;min-height:133px;padding:23px 21px;border-radius:11px}.mg-tile-top{display:block}.mg-tile-icon{width:43px;height:43px}.mg-tile-arrow{position:absolute;right:16px;top:16px;font-size:15px}.mg-home-tile>div:nth-child(2){padding-right:7px}.mg-home-tile h2{font-size:19px!important;margin-bottom:7px!important}.mg-home-tile p{font-size:12px;line-height:1.6}.mg-tile-letters{padding-top:21px}.mg-intro-line{margin-bottom:20px}}\n@media(prefers-reduced-motion:reduce){.mg-home-tile,.mg-tile-arrow{transition:none}.mg-home-tile:hover{transform:none}}\n";document.head.append(mgStyle);

